    ('cholera', 3, 'Early consultation for worsening diarrhea, vomiting or signs of dehydration'),
    ('rabies', 0, 'Immediate washing of any bite or scratch with soap and running water for at least 15 minutes, before travel to an Animal Bite Treatment Center'),
    ('rabies', 1, 'Same-day presentation to an Animal Bite Treatment Center or emergency department for PEP assessment after any animal bite or scratch'),
    ('rabies', 2, 'Completion of every scheduled vaccine dose on the assigned days, with the vaccination card kept for future exposures'),
    ('schistosomiasis', 0, 'Completion of the full praziquantel dose on the treatment day, taken with food'),
    ('schistosomiasis', 1, 'Avoidance of wading, bathing, swimming or washing in streams, ponds and rice fields in endemic areas'),
