INSERT INTO public.clinical_references (id, disease_id, position, source_name, citation_text, url, specialty, is_mother_book) VALUES
    ('ref_dengue_1', 'dengue', 0, 'Harrison''s Principles of Internal Medicine', 'Loscalzo J, Fauci A, Kasper D, Hauser S, Longo D, Jameson JL, eds. Harrison''s Principles of Internal Medicine, 21st ed. New York: McGraw Hill; 2022.', NULL, 'Internal Medicine / Infectious Disease', true),
    ('ref_dengue_2', 'dengue', 1, 'StatPearls - Dengue Fever', 'Pescador Ruschel MA, Panda PK, Farmer A. Dengue Fever. [Updated 2026 Mar 29]. In: StatPearls [Internet]. Treasure Island (FL): StatPearls Publishing; 2026 Jan-.', 'https://www.ncbi.nlm.nih.gov/books/NBK430732/', 'Infectious Disease', false),
    ('ref_dengue_3', 'dengue', 2, 'WHO Fact Sheet - Dengue and severe dengue', 'World Health Organization. Dengue and severe dengue. Fact sheet. Geneva: WHO.', 'https://www.who.int/news-room/fact-sheets/detail/dengue-and-severe-dengue', 'Public Health / Infectious Disease', false),
    ('ref_dengue_4', 'dengue', 3, 'DOH Philippines - 4S against dengue', 'Department of Health (Philippines). DOH reminds public to do 4S vs dengue as cases start to rise. Press release.', 'https://doh.gov.ph/press-release/DOH-reminds-public-to-do-4S-vs-dengue-as-cases-start-to-rise/', 'Public Health', false),
    ('ref_typhoid_fever_1', 'typhoid_fever', 0, 'Harrison''s Principles of Internal Medicine', 'Loscalzo J, Fauci A, Kasper D, Hauser S, Longo D, Jameson JL, eds. Harrison''s Principles of Internal Medicine, 21st ed. New York: McGraw Hill; 2022.', NULL, 'Internal Medicine / Infectious Disease', true),
    ('ref_typhoid_fever_2', 'typhoid_fever', 1, 'StatPearls - Typhoid Fever', 'Swinkels HM, Jenks JD, DeVos E. Typhoid Fever. [Updated 2024 Apr 19]. In: StatPearls [Internet]. Treasure Island (FL): StatPearls Publishing; 2026 Jan-.', 'https://www.ncbi.nlm.nih.gov/books/NBK557513/', 'Infectious Disease', false),
    ('ref_typhoid_fever_3', 'typhoid_fever', 2, 'WHO Fact Sheet - Typhoid', 'World Health Organization. Typhoid. Fact sheet. Geneva: WHO.', 'https://www.who.int/news-room/fact-sheets/detail/typhoid', 'Public Health / Infectious Disease', false),
    ('ref_typhoid_fever_4', 'typhoid_fever', 3, 'CDC - Typhoid and Paratyphoid Fever: Clinical Overview', 'Centers for Disease Control and Prevention. Clinical Overview of Typhoid and Paratyphoid Fever. Atlanta: CDC.', 'https://www.cdc.gov/typhoid-fever/hcp/clinical-overview/index.html', 'Infectious Disease', false),
    ('ref_leptospirosis_1', 'leptospirosis', 0, 'Harrison''s Principles of Internal Medicine', 'Loscalzo J, Fauci A, Kasper D, Hauser S, Longo D, Jameson JL, eds. Harrison''s Principles of Internal Medicine, 21st ed. New York: McGraw Hill; 2022.', NULL, 'Internal Medicine / Infectious Disease', true),
    ('ref_leptospirosis_2', 'leptospirosis', 1, 'StatPearls - Leptospirosis', 'Wang S, Dunn N. Leptospirosis. [Updated 2024 Sep 10]. In: StatPearls [Internet]. Treasure Island (FL): StatPearls Publishing; 2026 Jan-.', 'https://www.ncbi.nlm.nih.gov/books/NBK441858/', 'Infectious Disease', false),
    ('ref_leptospirosis_3', 'leptospirosis', 2, 'CDC - Clinical Overview of Leptospirosis', 'Centers for Disease Control and Prevention. Clinical Overview of Leptospirosis. Atlanta: CDC.', 'https://www.cdc.gov/leptospirosis/hcp/clinical-overview/index.html', 'Infectious Disease', false),
    ('ref_leptospirosis_4', 'leptospirosis', 3, 'CDC Yellow Book 2024 - Leptospirosis', 'Centers for Disease Control and Prevention. CDC Yellow Book 2024: Health Information for International Travel. Leptospirosis. New York: Oxford University Press; 2023.', 'https://wwwnc.cdc.gov/travel/yellowbook/2024/infections-diseases/leptospirosis', 'Travel Medicine / Infectious Disease', false),
    ('ref_leptospirosis_5', 'leptospirosis', 4, 'PhilHealth - Leptospirosis Policy Statements', 'Philippine Health Insurance Corporation. Leptospirosis Policy Statements (consensus based on the Philippine Leptospirosis Task Force Clinical Practice Guidelines, 2010).', 'https://www.philhealth.gov.ph/partners/providers/pdf/Leptospirosis_Policy_Statements.pdf', 'Infectious Disease / Philippine Guideline', false),
    ('ref_tuberculosis_1', 'tuberculosis', 0, 'Harrison''s Principles of Internal Medicine', 'Loscalzo J, Fauci A, Kasper D, Hauser S, Longo D, Jameson JL, eds. Harrison''s Principles of Internal Medicine, 21st ed. New York: McGraw Hill; 2022.', NULL, 'Internal Medicine / Pulmonology / Infectious Disease', true),
    ('ref_tuberculosis_2', 'tuberculosis', 1, 'StatPearls - Tuberculosis Overview', 'Tobin EH, Tristram D. Tuberculosis Overview. [Updated 2024 Dec 22]. In: StatPearls [Internet]. Treasure Island (FL): StatPearls Publishing; 2026 Jan-.', 'https://www.ncbi.nlm.nih.gov/books/NBK441916/', 'Infectious Disease / Pulmonology', false),
    ('ref_tuberculosis_3', 'tuberculosis', 2, 'WHO Fact Sheet - Tuberculosis', 'World Health Organization. Tuberculosis. Fact sheet. Geneva: WHO.', 'https://www.who.int/news-room/fact-sheets/detail/tuberculosis', 'Public Health / Infectious Disease', false),
    ('ref_tuberculosis_4', 'tuberculosis', 3, 'DOH Philippines - Tuberculosis Control Program', 'Department of Health (Philippines). Tuberculosis Control Program. Manila: DOH.', 'https://doh.gov.ph/uhc/health-programs/tuberculosis-control-program/', 'Public Health / Philippine Program', false),
    ('ref_tuberculosis_5', 'tuberculosis', 4, 'NTP Manual of Procedures, 6th Edition', 'Department of Health (Philippines), National Tuberculosis Control Program. Manual of Procedures, 6th ed. Manila: DOH.', 'https://ntp.doh.gov.ph/download/ntp-mop-6th-edition/', 'Public Health / Philippine Guideline', false),
    ('ref_malaria_1', 'malaria', 0, 'Harrison''s Principles of Internal Medicine', 'Loscalzo J, Fauci A, Kasper D, Hauser S, Longo D, Jameson JL, eds. Harrison''s Principles of Internal Medicine, 21st ed. New York: McGraw Hill; 2022.', NULL, 'Internal Medicine / Infectious Disease', true),
    ('ref_malaria_2', 'malaria', 1, 'StatPearls - Malaria', 'Buck E, Finnigan NA. Malaria. [Updated 2023 Jul 31]. In: StatPearls [Internet]. Treasure Island (FL): StatPearls Publishing; 2026 Jan-.', 'https://www.ncbi.nlm.nih.gov/books/NBK551711/', 'Infectious Disease', false),
    ('ref_malaria_3', 'malaria', 2, 'WHO Fact Sheet - Malaria', 'World Health Organization. Malaria. Fact sheet. Geneva: WHO.', 'https://www.who.int/news-room/fact-sheets/detail/malaria', 'Public Health / Infectious Disease', false),
    ('ref_malaria_4', 'malaria', 3, 'CDC - Treatment of Uncomplicated Malaria', 'Centers for Disease Control and Prevention. Treatment of Uncomplicated Malaria. Clinical Guidance: Malaria Diagnosis and Treatment in the U.S. Atlanta: CDC; updated 2026 Aug 17.', 'https://www.cdc.gov/malaria/hcp/clinical-guidance/treatment-of-uncomplicated-malaria.html', 'Infectious Disease', false),
    ('ref_malaria_5', 'malaria', 4, 'CDC - Treatment of Severe Malaria', 'Centers for Disease Control and Prevention. Treatment of Severe Malaria. Clinical Guidance: Malaria Diagnosis and Treatment in the U.S. Atlanta: CDC.', 'https://www.cdc.gov/malaria/hcp/clinical-guidance/treatment-of-severe-malaria-1.html', 'Infectious Disease', false),
    ('ref_malaria_6', 'malaria', 5, 'Emerging Infectious Diseases - P. knowlesi in the Philippines', 'Luchavez J, Espino F, Curameng P, et al. Human infections with Plasmodium knowlesi, the Philippines. Emerg Infect Dis. 2008;14(5):811-813.', 'https://wwwnc.cdc.gov/eid/article/14/5/07-1407_article', 'Infectious Disease / Parasitology', false),
    ('ref_community_acquired_pneumonia_1', 'community_acquired_pneumonia', 0, 'Harrison''s Principles of Internal Medicine', 'Loscalzo J, Fauci A, Kasper D, Hauser S, Longo D, Jameson JL, eds. Harrison''s Principles of Internal Medicine, 21st ed. New York: McGraw Hill; 2022.', NULL, 'Internal Medicine', true),
    ('ref_community_acquired_pneumonia_2', 'community_acquired_pneumonia', 1, 'PSMID Philippine CPG on Adult CAP 2020', 'Philippine Society for Microbiology and Infectious Diseases, Philippine College of Physicians, et al. Clinical Practice Guidelines: Management and Prevention of Adult Community-Acquired Pneumonia. 2020.', 'https://psmid.org/wp-content/uploads/2025/10/2020-Community-Acquired-Pneumonia-Clinical-Practice-Guidelines.pdf', 'Infectious Disease', false),
    ('ref_community_acquired_pneumonia_3', 'community_acquired_pneumonia', 2, 'StatPearls', 'Regunath H, Oba Y. Community-Acquired Pneumonia. In: StatPearls [Internet]. Treasure Island (FL): StatPearls Publishing. Updated 2024 Jan 26.', 'https://www.ncbi.nlm.nih.gov/books/NBK430749/', 'Pulmonology', false),
