INSERT INTO public.disease_medicines (disease_id, medicine_id, position, safety, note) VALUES
    ('dengue', 'med_paracetamol', 0, 'safe', 'Preferred antipyretic/analgesic in dengue (WHO, StatPearls); adhere to maximum daily dose, especially with hepatic involvement.'),
    ('dengue', 'med_ors', 1, 'safe', 'Oral fluids such as ORS support hydration in outpatient dengue without warning signs.'),
    ('dengue', 'med_ibuprofen', 2, 'avoid', 'NSAIDs increase bleeding risk in dengue; WHO advises against them.'),
    ('dengue', 'med_mefenamic_acid', 3, 'avoid', 'NSAID; antiplatelet effect and GI bleeding risk in the setting of dengue thrombocytopenia.'),
    ('dengue', 'med_aspirin', 4, 'avoid', 'Antiplatelet salicylate increases hemorrhage risk; also carries Reye syndrome risk in children.'),
    ('typhoid_fever', 'med_azithromycin', 0, 'safe', 'Oral option for uncomplicated typhoid where fluoroquinolone resistance is common and for XDR strains.'),
    ('typhoid_fever', 'med_ceftriaxone', 1, 'safe', 'IV therapy of choice for severe typhoid or where fluoroquinolone resistance prevails (ineffective against XDR strains).'),
    ('typhoid_fever', 'med_ciprofloxacin', 2, 'caution', 'Effective only for fluoroquinolone-susceptible isolates; non-susceptibility is widespread in Asia, so use is guided by susceptibility testing.'),
    ('typhoid_fever', 'med_paracetamol', 3, 'safe', 'Symptomatic antipyretic/analgesic for fever and headache.'),
    ('leptospirosis', 'med_doxycycline', 0, 'safe', 'Drug of choice for mild leptospirosis (100 mg BID x 7 days) and for post-exposure/pre-exposure prophylaxis (200 mg regimens); not used in pregnancy.'),
    ('leptospirosis', 'med_amoxicillin', 1, 'safe', 'Oral alternative for mild disease, e.g., when doxycycline is contraindicated.'),
    ('leptospirosis', 'med_azithromycin', 2, 'safe', 'Alternative for mild disease and listed option for moderate-severe disease in the Philippine guideline.'),
    ('leptospirosis', 'med_ceftriaxone', 3, 'safe', 'IV option (1 g every 24 h) for moderate-severe leptospirosis, equivalent alternative to penicillin G.'),
    ('leptospirosis', 'med_paracetamol', 4, 'safe', 'Symptomatic antipyretic/analgesic; dose limits observed if hepatic involvement.'),
    ('leptospirosis', 'med_ibuprofen', 5, 'avoid', 'NSAIDs are nephrotoxic and impair platelet function; risky given frequent acute kidney injury and bleeding in leptospirosis.'),
    ('tuberculosis', 'med_isoniazid', 0, 'safe', 'First-line (H) in intensive and continuation phases; monitor for hepatotoxicity and give pyridoxine to prevent neuropathy.'),
    ('tuberculosis', 'med_rifampicin', 1, 'safe', 'First-line (R) sterilizing drug; hepatotoxic, colors body fluids orange, and a potent enzyme inducer with many drug interactions.'),
    ('tuberculosis', 'med_pyrazinamide', 2, 'safe', 'First-line (Z) in the 2-month intensive phase; hepatotoxicity and arthralgia are notable adverse effects.'),
    ('tuberculosis', 'med_ethambutol', 3, 'safe', 'First-line (E) in the intensive phase; causes dose-related optic neuritis, requiring baseline and periodic vision checks.'),
    ('tuberculosis', 'med_warfarin', 4, 'caution', 'Rifampicin induces warfarin metabolism, markedly reducing anticoagulant effect; close INR monitoring and dose adjustment needed.'),
    ('tuberculosis', 'med_prednisone', 5, 'caution', 'Systemic immunosuppression increases the risk of TB reactivation/progression; used in TB only for specific indications under treatment.'),
    ('malaria', 'med_artemether_lumefantrine', 0, 'safe', 'First-line ACT for uncomplicated P. falciparum and follow-on after IV artesunate; must be taken with fatty food for absorption.'),
    ('malaria', 'med_doxycycline', 1, 'safe', 'Option for malaria chemoprophylaxis in travelers (daily, continued 4 weeks after exposure); not used in pregnancy or young children.'),
    ('malaria', 'med_paracetamol', 2, 'safe', 'Symptomatic antipyretic for malarial fever alongside antimalarial therapy.'),
    ('community_acquired_pneumonia', 'med_amoxicillin', 0, 'safe', 'First-line oral option (1 g three times daily) for low-risk CAP without comorbidities per PSMID 2020.'),
    ('community_acquired_pneumonia', 'med_azithromycin', 1, 'safe', 'Oral option for low-risk CAP and the macrolide partner to a beta-lactam in moderate- and high-risk CAP.'),
    ('community_acquired_pneumonia', 'med_clarithromycin', 2, 'caution', 'Guideline macrolide option, but QT prolongation and strong CYP3A4 inhibition require review of co-medications.'),
    ('community_acquired_pneumonia', 'med_coamoxiclav', 3, 'safe', 'Beta-lactam of choice for low-risk CAP with stable comorbidities, with or without a macrolide or doxycycline.'),
    ('community_acquired_pneumonia', 'med_ceftriaxone', 4, 'safe', 'IV non-pseudomonal beta-lactam combined with a macrolide for hospitalized moderate- and high-risk CAP.'),
    ('community_acquired_pneumonia', 'med_doxycycline', 5, 'safe', 'Alternative oral agent or add-on for atypical coverage in low-risk CAP with comorbidities.'),
    ('community_acquired_pneumonia', 'med_oseltamivir', 6, 'safe', 'Added when CAP is associated with suspected or confirmed influenza.'),
    ('community_acquired_pneumonia', 'med_paracetamol', 7, 'safe', 'Symptomatic control of fever and pleuritic pain.'),
    ('community_acquired_pneumonia', 'med_prednisone', 8, 'caution', 'Systemic corticosteroids are recommended against in nonsevere CAP; considered only in severe CAP (ATS 2025), not influenza pneumonia.'),
    ('influenza', 'med_oseltamivir', 0, 'safe', 'Neuraminidase inhibitor of choice; 75 mg twice daily for 5 days, renally dose-adjusted, preferred in pregnancy.'),
    ('influenza', 'med_paracetamol', 1, 'safe', 'Symptomatic relief of fever, headache and myalgia.'),
    ('influenza', 'med_aspirin', 2, 'caution', 'Salicylates are not given to persons aged 18 or younger with influenza because of Reye syndrome risk (CDC); adult antiplatelet use is not affected.'),
    ('influenza', 'med_prednisone', 3, 'avoid', 'IDSA 2018 recommends against adjunctive corticosteroids in influenza unless indicated for another condition.'),
    ('covid19', 'med_nirmatrelvir_ritonavir', 0, 'caution', 'Recommended for high-risk non-severe COVID-19 within 5 days of onset, but ritonavir''s strong CYP3A inhibition causes serious interactions (boxed warning); renal dose adjustment required.'),
    ('covid19', 'med_paracetamol', 1, 'safe', 'Symptomatic control of fever, headache and myalgia.'),
    ('covid19', 'med_prednisone', 2, 'caution', 'Systemic corticosteroids (dexamethasone preferred) are recommended only for severe/critical COVID-19 and not for non-severe disease.'),
    ('measles', 'med_paracetamol', 0, 'safe', 'Supportive control of high fever and discomfort.'),
    ('measles', 'med_amoxicillin', 1, 'safe', 'No antiviral effect; used only for secondary bacterial complications such as otitis media and pneumonia.'),
    ('acute_gastroenteritis', 'med_ors', 0, 'safe', 'Reduced-osmolarity ORS is first-line therapy for mild to moderate dehydration at all ages.'),
    ('acute_gastroenteritis', 'med_loperamide', 1, 'caution', 'Acceptable for acute watery diarrhea in immunocompetent adults; avoided with fever, bloody/inflammatory diarrhea or suspected toxic megacolon.'),
    ('acute_gastroenteritis', 'med_azithromycin', 2, 'safe', 'Empiric agent when antibiotics are indicated (febrile dysentery, febrile travelers, immunocompromised); not used for routine watery diarrhea.'),
    ('acute_gastroenteritis', 'med_ciprofloxacin', 3, 'caution', 'Empiric fluoroquinolone option only when antibiotics are indicated, chosen according to local susceptibility patterns.'),
    ('acute_gastroenteritis', 'med_doxycycline', 4, 'safe', 'Tetracyclines are active against Vibrio cholerae and are used with rehydration in severe cholera.'),
    ('acute_gastroenteritis', 'med_paracetamol', 5, 'safe', 'Symptomatic control of fever and discomfort.'),
    ('acute_gastroenteritis', 'med_ibuprofen', 6, 'caution', 'NSAIDs raise the risk of acute kidney injury in volume-depleted, dehydrated patients.'),
    ('urinary_tract_infection', 'med_nitrofurantoin', 0, 'safe', 'First-line for acute uncomplicated cystitis; not used for pyelonephritis (poor tissue levels) and avoided when eGFR is below 45 mL/min/1.73 m2 or at term in pregnancy.'),
    ('urinary_tract_infection', 'med_ceftriaxone', 1, 'safe', 'Parenteral cephalosporin used as an initial dose or inpatient therapy for pyelonephritis.'),
    ('urinary_tract_infection', 'med_ciprofloxacin', 2, 'caution', 'Option for pyelonephritis where local resistance is 10% or less; reserved rather than used first-line for cystitis because of resistance and serious adverse effects (tendon, nerve, CNS).'),
    ('urinary_tract_infection', 'med_amoxicillin', 3, 'caution', 'High E. coli resistance limits empiric use; used only when the organism is known to be susceptible (e.g., pregnancy per NICE).'),
    ('urinary_tract_infection', 'med_coamoxiclav', 4, 'caution', 'Beta-lactam alternative generally reserved for culture-guided therapy; beta-lactams are less effective than first-line agents for empiric cystitis.'),
    ('urinary_tract_infection', 'med_paracetamol', 5, 'safe', 'Recommended analgesic for UTI-related pain (NICE).'),
    ('urinary_tract_infection', 'med_ibuprofen', 6, 'caution', 'Alternative analgesic if suitable (NICE); NSAIDs carry renal risk in dehydration or pyelonephritis.'),
    ('peptic_ulcer_disease', 'med_omeprazole', 0, 'safe', 'Proton pump inhibitor for ulcer healing, a component of H. pylori regimens, and prophylaxis with ongoing NSAID or aspirin use.'),
    ('peptic_ulcer_disease', 'med_amoxicillin', 1, 'safe', 'Component of H. pylori eradication regimens (e.g., vonoprazan-amoxicillin dual therapy).'),
    ('peptic_ulcer_disease', 'med_clarithromycin', 2, 'caution', 'ACG 2024 advises against clarithromycin triple therapy unless clarithromycin susceptibility has been demonstrated, because resistance sharply lowers eradication rates.'),
    ('peptic_ulcer_disease', 'med_ibuprofen', 3, 'avoid', 'NSAIDs are the second leading cause of peptic ulcers and increase the risk of ulcer bleeding and perforation.'),
    ('peptic_ulcer_disease', 'med_mefenamic_acid', 4, 'avoid', 'NSAID; impairs prostaglandin-mediated mucosal protection and increases ulcer and bleeding risk.'),
    ('peptic_ulcer_disease', 'med_aspirin', 5, 'caution', 'Even low-dose aspirin causes ulcers and bleeding; when required for cardiovascular prevention it is generally continued with PPI co-therapy rather than stopped.'),
    ('peptic_ulcer_disease', 'med_clopidogrel', 6, 'caution', 'Antiplatelet effect increases the risk and severity of ulcer bleeding.'),
    ('peptic_ulcer_disease', 'med_warfarin', 7, 'caution', 'Anticoagulation increases the risk and severity of bleeding from peptic ulcers.'),
    ('peptic_ulcer_disease', 'med_prednisone', 8, 'caution', 'Systemic corticosteroids are an ulcer risk factor, particularly when combined with NSAIDs.'),
    ('peptic_ulcer_disease', 'med_paracetamol', 9, 'safe', 'Preferred analgesic alternative to NSAIDs in patients with peptic ulcer disease.'),
    ('hypertension', 'med_amlodipine', 0, 'safe', 'First-line dihydropyridine calcium channel blocker; peripheral edema is the common adverse effect.'),
    ('hypertension', 'med_losartan', 1, 'safe', 'First-line ARB; monitor potassium and creatinine; contraindicated in pregnancy.'),
    ('hypertension', 'med_enalapril', 2, 'safe', 'First-line ACE inhibitor; cough, angioedema and hyperkalemia possible; contraindicated in pregnancy.'),
    ('hypertension', 'med_hydrochlorothiazide', 3, 'safe', 'First-line thiazide diuretic; may cause hypokalemia, hyperglycemia and hyperuricemia.'),
    ('hypertension', 'med_spironolactone', 4, 'caution', 'Preferred fourth-line agent for resistant hypertension; hyperkalemia risk, especially with ACE inhibitors/ARBs or reduced eGFR.'),
    ('hypertension', 'med_metoprolol', 5, 'caution', 'Not first-line for uncomplicated hypertension; used for compelling indications such as HFrEF, post-MI or atrial fibrillation rate control.'),
    ('hypertension', 'med_furosemide', 6, 'caution', 'Loop diuretic not first-line for hypertension alone; preferred when eGFR is below 30 or with volume overload/heart failure.'),
    ('hypertension', 'med_ibuprofen', 7, 'caution', 'NSAIDs can raise blood pressure, reduce antihypertensive efficacy and increase hyperkalemia risk with RAAS inhibitors.'),
    ('hypertension', 'med_mefenamic_acid', 8, 'caution', 'NSAID; same blood pressure and renal cautions as other NSAIDs.'),
    ('hypertension', 'med_prednisone', 9, 'caution', 'Systemic glucocorticoids cause sodium and fluid retention and can raise blood pressure.'),
    ('type2_diabetes', 'med_metformin', 0, 'safe', 'Usual first-line agent; low hypoglycemia risk; contraindicated when eGFR is below 30 mL/min/1.73 m2.'),
    ('type2_diabetes', 'med_dapagliflozin', 1, 'safe', 'SGLT2 inhibitor with cardiorenal benefit in heart failure and CKD; genital mycotic infection and euglycemic ketoacidosis are recognized risks.'),
    ('type2_diabetes', 'med_gliclazide', 2, 'caution', 'Effective and inexpensive sulfonylurea but carries hypoglycemia risk, particularly in older adults, renal impairment or missed meals.'),
    ('type2_diabetes', 'med_atorvastatin', 3, 'safe', 'Statin therapy is recommended for cardiovascular risk reduction in most adults with diabetes.'),
    ('type2_diabetes', 'med_losartan', 4, 'safe', 'ARB preferred for hypertension with albuminuria in diabetes to slow kidney disease progression.'),
    ('type2_diabetes', 'med_enalapril', 5, 'safe', 'ACE inhibitor preferred for hypertension with albuminuria in diabetes; not combined with an ARB.'),
    ('type2_diabetes', 'med_prednisone', 6, 'caution', 'Systemic glucocorticoids raise blood glucose and can destabilize glycemic control.'),
    ('type2_diabetes', 'med_metoprolol', 7, 'caution', 'Beta-blockers can mask adrenergic warning symptoms of hypoglycemia (e.g., tremor, palpitations).'),
    ('asthma', 'med_budesonide_formoterol', 0, 'safe', 'GINA Track 1 preferred reliever (as-needed low-dose) and maintenance-and-reliever therapy; reduces severe exacerbations versus SABA-based regimens.'),
    ('asthma', 'med_salbutamol', 1, 'safe', 'Short-acting reliever and first-line bronchodilator in acute exacerbations; SABA-only treatment without ICS is not recommended.'),
    ('asthma', 'med_prednisone', 2, 'safe', 'Short oral course (40-50 mg daily for 5-7 days in adults) for exacerbations; repeated or long-term use carries significant systemic adverse effects.'),
    ('asthma', 'med_metoprolol', 3, 'caution', 'Beta-blockers can cause asthma symptoms or exacerbations (GINA); beta-1 selective agents carry lower risk and are used only with a strong indication and close supervision.'),
    ('asthma', 'med_aspirin', 4, 'caution', 'Can precipitate severe bronchospasm in aspirin/NSAID-exacerbated respiratory disease; previous reactions are asked about before prescribing.'),
    ('asthma', 'med_ibuprofen', 5, 'caution', 'NSAID; avoided in patients with a history of NSAID-induced bronchospasm.'),
    ('asthma', 'med_mefenamic_acid', 6, 'caution', 'NSAID; same precaution regarding NSAID-exacerbated respiratory disease.'),
    ('copd', 'med_salbutamol', 0, 'safe', 'Short-acting beta-2 agonist used as needed for symptom relief and intensified during exacerbations.'),
    ('copd', 'med_budesonide_formoterol', 1, 'caution', 'ICS/LABA reserved for patients with exacerbations and raised blood eosinophils; inhaled corticosteroids increase pneumonia risk in COPD.'),
    ('copd', 'med_prednisone', 2, 'caution', 'Short course (about 40 mg for 5 days) for exacerbations; long-term systemic corticosteroid maintenance is not used due to adverse effects.'),
    ('copd', 'med_amoxicillin', 3, 'safe', 'NICE first-choice oral antibiotic for exacerbations with increased sputum purulence or volume.'),
    ('copd', 'med_doxycycline', 4, 'safe', 'NICE first-choice oral alternative for exacerbations requiring antibiotics.'),
    ('copd', 'med_clarithromycin', 5, 'safe', 'NICE first-choice macrolide option for exacerbations requiring antibiotics; check for interacting drugs.'),
    ('copd', 'med_coamoxiclav', 6, 'safe', 'NICE second-line option when first-choice therapy fails or treatment-failure risk is higher.'),
    ('copd', 'med_azithromycin', 7, 'caution', 'Long-term prophylaxis reduces exacerbations in selected frequent exacerbators; QT prolongation, hearing loss and resistance are concerns.'),
    ('copd', 'med_metoprolol', 8, 'caution', 'Cardioselective beta-blocker; Cochrane review found no worsening of FEV1 or symptoms, so it should not be withheld when a cardiac indication exists.'),
    ('acute_coronary_syndrome', 'med_aspirin', 0, 'safe', 'Loading dose chewed at presentation then long-term low-dose therapy; cornerstone antiplatelet agent in all ACS.'),
    ('acute_coronary_syndrome', 'med_clopidogrel', 1, 'safe', 'P2Y12 inhibitor for dual antiplatelet therapy; ticagrelor or prasugrel are generally preferred with PCI, clopidogrel with fibrinolysis or high bleeding risk.'),
    ('acute_coronary_syndrome', 'med_atorvastatin', 2, 'safe', 'High-intensity statin (e.g., 80 mg) started early in all ACS patients without contraindication.'),
    ('acute_coronary_syndrome', 'med_metoprolol', 3, 'caution', 'Oral beta-blocker within 24 hours if stable; avoided in heart failure signs, low-output state, cardiogenic shock risk or bradycardia/heart block.'),
    ('acute_coronary_syndrome', 'med_enalapril', 4, 'caution', 'ACE inhibitor indicated especially with LVEF 40% or less, hypertension, diabetes or CKD; monitor for hypotension, renal function and potassium.'),
    ('acute_coronary_syndrome', 'med_ibuprofen', 5, 'avoid', 'NSAID boxed warning for MI and stroke risk; label advises avoiding use after recent MI and contraindicates use around CABG.'),
    ('acute_coronary_syndrome', 'med_mefenamic_acid', 6, 'avoid', 'NSAID class carries the same boxed warning for serious cardiovascular thrombotic events.'),
    ('acute_coronary_syndrome', 'med_sumatriptan', 7, 'avoid', 'Triptans are contraindicated in ischemic coronary artery disease, prior MI or coronary vasospasm (FDA label).'),
    ('heart_failure', 'med_furosemide', 0, 'safe', 'Loop diuretic for relief of congestion; monitor electrolytes, renal function and volume status.'),
    ('heart_failure', 'med_dapagliflozin', 1, 'safe', 'SGLT2 inhibitor reduces mortality and HF hospitalization in HFrEF regardless of diabetes status, and hospitalization in HFmrEF/HFpEF.'),
    ('heart_failure', 'med_enalapril', 2, 'safe', 'ACE inhibitor reduces mortality in HFrEF when ARNI is not feasible; monitor potassium, creatinine and for angioedema.'),
    ('heart_failure', 'med_losartan', 3, 'safe', 'ARB used in HFrEF when ACE inhibitors are not tolerated (e.g., cough); monitor potassium and renal function.'),
    ('heart_failure', 'med_spironolactone', 4, 'caution', 'MRA reduces mortality in NYHA II-IV HFrEF; used only with eGFR above 30 and potassium below 5.0 because of hyperkalemia risk.'),
    ('heart_failure', 'med_metoprolol', 5, 'caution', 'Only the sustained-release succinate form is evidence-based in HFrEF; started low and titrated when euvolemic, not in acute decompensation or shock.'),
    ('heart_failure', 'med_hydrochlorothiazide', 6, 'caution', 'Thiazide added to loop diuretic for diuretic resistance; risk of hyponatremia, hypokalemia and renal dysfunction.'),
    ('heart_failure', 'med_ibuprofen', 7, 'avoid', 'NSAIDs cause sodium and fluid retention and about a two-fold increase in HF hospitalization; listed among drugs to avoid in HF.'),
    ('heart_failure', 'med_mefenamic_acid', 8, 'avoid', 'NSAID class effect: fluid retention and worsening of heart failure.'),
    ('ischemic_stroke', 'med_aspirin', 0, 'safe', 'Started within 24-48 hours of onset after hemorrhage is excluded; usually deferred for 24 hours after IV thrombolysis.'),
    ('ischemic_stroke', 'med_clopidogrel', 1, 'safe', 'Short-term dual antiplatelet therapy with aspirin is preferred over thrombolysis for minor non-disabling ischemic stroke.'),
    ('ischemic_stroke', 'med_atorvastatin', 2, 'safe', 'High-intensity statin (e.g., 80 mg daily) for secondary prevention of atherosclerotic stroke.'),
    ('ischemic_stroke', 'med_warfarin', 3, 'caution', 'Anticoagulation for cardioembolic stroke with atrial fibrillation; timing depends on infarct size and hemorrhage risk, and DOACs are generally preferred in nonvalvular AF.'),
    ('ischemic_stroke', 'med_paracetamol', 4, 'safe', 'Antipyretic used to treat fever, since hyperthermia worsens outcome after stroke.'),
    ('ischemic_stroke', 'med_losartan', 5, 'caution', 'Used for long-term blood pressure control in secondary prevention; aggressive acute-phase lowering is avoided.'),
    ('ischemic_stroke', 'med_sumatriptan', 6, 'avoid', 'Triptans are contraindicated with a history of stroke or TIA (FDA label).'),
    ('migraine', 'med_sumatriptan', 0, 'safe', 'Indicated for acute migraine with or without aura; contraindicated in ischemic heart disease, stroke/TIA, hemiplegic or basilar migraine and uncontrolled hypertension.'),
    ('migraine', 'med_ibuprofen', 1, 'safe', 'First-line NSAID for acute attacks (400-600 mg); use on 15 or more days per month risks medication-overuse headache.'),
    ('migraine', 'med_paracetamol', 2, 'safe', 'Acute treatment option for mild-to-moderate attacks, including when NSAIDs are unsuitable; overuse risks medication-overuse headache.'),
    ('migraine', 'med_metoprolol', 3, 'safe', 'Beta-blocker used for migraine prophylaxis in frequent or disabling migraine.'),
    ('chikungunya', 'med_paracetamol', 0, 'safe', 'Recommended for fever and pain until dengue is ruled out (WHO, StatPearls); adhere to the maximum daily dose.'),
    ('chikungunya', 'med_ibuprofen', 1, 'avoid', 'Avoided while dengue has not been excluded because NSAIDs increase bleeding risk (WHO, StatPearls); after dengue is excluded, NSAIDs may be used for arthralgia.'),
    ('chikungunya', 'med_mefenamic_acid', 2, 'avoid', 'NSAID; avoided while dengue has not been excluded because of bleeding risk (WHO, StatPearls).'),
    ('chikungunya', 'med_aspirin', 3, 'avoid', 'StatPearls advises avoiding aspirin (and NSAIDs) until dengue is excluded, because of bleeding risk.'),
    ('hepatitis_b', 'med_tenofovir', 0, 'safe', 'First-line oral antiviral for chronic hepatitis B (WHO); high barrier to resistance (StatPearls). Most patients require long-term therapy.'),
    ('hepatitis_b', 'med_entecavir', 1, 'safe', 'First-line oral antiviral for chronic hepatitis B (WHO); high barrier to resistance (StatPearls).'),
    ('hepatitis_b', 'med_prednisone', 2, 'caution', 'Immunosuppression is associated with HBV reactivation (StatPearls); HBV status is relevant before systemic corticosteroid therapy, particularly prolonged courses.'),
    ('hepatitis_a', 'med_paracetamol', 0, 'caution', 'StatPearls advises limiting paracetamol dosing in hepatitis A, and WHO lists paracetamol among unnecessary medications that can adversely affect the liver.'),
    ('hepatitis_a', 'med_rifampicin', 1, 'caution', 'Listed by StatPearls as an option for severe pruritus in cholestatic hepatitis A; it is itself potentially hepatotoxic, so use is specialist-directed with liver test monitoring.'),
    ('hepatitis_a', 'med_isoniazid', 2, 'avoid', 'Recognized hepatotoxic drug; StatPearls advises avoiding hepatotoxic drugs during acute hepatitis A.'),
    ('hepatitis_a', 'med_pyrazinamide', 3, 'avoid', 'Recognized hepatotoxic drug; StatPearls advises avoiding hepatotoxic drugs during acute hepatitis A.'),
    ('cholera', 'med_ors', 0, 'safe', 'Mainstay of treatment; ORS alone suffices for most cases, and severely dehydrated patients receive IV fluids plus ORS (WHO).'),
    ('cholera', 'med_zinc_sulfate', 1, 'safe', 'Adjunct for children older than 6 months with acute infectious diarrhea, 20 mg/day for 10-14 days (Philippine CPG).'),
    ('cholera', 'med_azithromycin', 2, 'safe', 'Philippine CPG first-line option for suspected/confirmed cholera: 1 g single dose in adults; 20 mg/kg single dose or 10 mg/kg daily for 3 days in children.'),
    ('cholera', 'med_doxycycline', 3, 'safe', 'Philippine CPG: adult alternative 100 mg twice daily for 3 days; 300 mg single dose for children over 8 years. CDC Yellow Book lists doxycycline as a reasonable first-line drug for travelers.'),
    ('cholera', 'med_ciprofloxacin', 4, 'safe', 'Philippine CPG adult option: 1-2 g single dose or 500 mg twice daily for 3 days; choice guided by local susceptibility.'),
    ('cholera', 'med_cotrimoxazole', 5, 'safe', 'Listed among alternative antibiotics for children with suspected/confirmed cholera in the Philippine CPG.'),
    ('cholera', 'med_loperamide', 6, 'avoid', 'The Philippine CPG does not recommend loperamide in adults with acute infectious diarrhea and advises against it in children because of serious adverse events; it does not address fluid loss.'),
    ('cholera', 'med_omeprazole', 7, 'caution', 'Reduced gastric acidity from acid-suppressing medicines increases susceptibility to V. cholerae infection (CDC Yellow Book).'),
    ('rabies', 'med_rabies_vaccine', 0, 'safe', 'Core of PEP for WHO category II and III exposures and of pre-exposure prophylaxis; no role once clinical rabies has developed (StatPearls).'),
    ('rabies', 'med_rabies_immunoglobulin', 1, 'safe', 'Indicated for category III exposures (and immunocompromised patients with category II); infiltrated into and around the wound within 7 days of the first vaccine dose. Not given to previously vaccinated persons.'),
    ('rabies', 'med_paracetamol', 2, 'safe', 'Antipyretic and analgesic used in supportive and palliative care of clinical rabies (often rectal when swallowing is impaired).'),
    ('schistosomiasis', 'med_praziquantel', 0, 'safe', 'Drug of choice for all major Schistosoma species; S. japonicum 60 mg/kg/day in three divided doses for one day (CDC). Used in DOH mass drug administration.'),
    ('schistosomiasis', 'med_paracetamol', 1, 'caution', 'Symptomatic relief of fever and pain (e.g., acute schistosomiasis); keep within maximum daily dose in patients with advanced liver disease.'),
    ('schistosomiasis', 'med_ibuprofen', 2, 'caution', 'NSAIDs increase gastrointestinal bleeding risk, a concern in hepatosplenic schistosomiasis with portal hypertension and varices; paracetamol is generally preferred.'),
    ('pertussis', 'med_azithromycin', 0, 'safe', 'Preferred antibiotic for treatment and post-exposure prophylaxis at all ages, including infants under 1 month (CDC, StatPearls).'),
    ('pertussis', 'med_clarithromycin', 1, 'caution', 'Alternative macrolide; macrolides are used with caution in infants under 1 month because of the association with infantile hypertrophic pyloric stenosis, where azithromycin is preferred.'),
    ('pertussis', 'med_cotrimoxazole', 2, 'caution', 'Alternative for macrolide allergy, intolerance or resistance; not used in infants under 2 months.'),
    ('hfmd', 'med_paracetamol', 0, 'safe', 'Used for fever and pain from mouth sores (StatPearls); weight-based pediatric dosing within the maximum daily dose.'),
    ('hfmd', 'med_ibuprofen', 1, 'safe', 'NSAIDs are listed by StatPearls for pain and fever in HFMD; adequate hydration is maintained because NSAIDs carry renal risk in dehydrated children.'),
    ('hfmd', 'med_ors', 2, 'safe', 'Oral fluids such as ORS help maintain hydration when painful oral ulcers reduce intake; dehydration is the most common complication (CDC).'),
    ('varicella', 'med_aciclovir', 0, 'safe', 'Oral aciclovir within 24 hours of rash onset for people older than 12 years or with chronic skin/lung disease, salicylate or steroid therapy; IV aciclovir for severe disease or immunocompromise (CDC). Not routinely recommended for healthy children (StatPearls).'),
    ('varicella', 'med_paracetamol', 1, 'safe', 'Preferred antipyretic in chickenpox (StatPearls, NHS); weight-based dosing within the maximum daily dose.'),
    ('varicella', 'med_cetirizine', 2, 'safe', 'Antihistamines are used for the pruritus of chickenpox (StatPearls, NHS), together with calamine lotion and cool compresses.'),
    ('varicella', 'med_aspirin', 3, 'avoid', 'Aspirin is avoided in chickenpox because of the risk of Reye syndrome (StatPearls); NHS advises no aspirin for children under 16.'),
    ('varicella', 'med_ibuprofen', 4, 'avoid', 'NHS advises against ibuprofen in chickenpox unless a doctor recommends it, because it may cause serious skin infections.'),
    ('varicella', 'med_prednisone', 5, 'caution', 'People on corticosteroid courses are at risk of severe varicella; CDC lists them for oral antiviral therapy and recommends IV aciclovir for immunocompromised patients, including those on prolonged high-dose steroids.'),
    ('hiv_infection', 'med_tld', 0, 'safe', 'Dolutegravir-based ART with a tenofovir + lamivudine backbone is WHO''s preferred first-line treatment for all populations, including pregnant women and women of childbearing potential (WHO 2019; StatPearls). TLD is the DOH''s recommended first-line ARV regimen in the Philippines (DOH, reported by PNA 2026).'),
    ('hiv_infection', 'med_cotrimoxazole', 1, 'safe', 'Prophylaxis when CD4 is below 200 cells/mm3 prevents Pneumocystis pneumonia and also protects against toxoplasmosis and some bacterial infections (StatPearls); alternatives are used in sulfa allergy.'),
    ('hiv_infection', 'med_tenofovir', 2, 'caution', 'Used in HIV only as part of a combination regimen (NRTI backbone with lamivudine or emtricitabine plus an integrase inhibitor, per StatPearls); hepatitis B status is checked at baseline because tenofovir is also active against HBV.'),
    ('hiv_infection', 'med_rifampicin', 3, 'caution', 'In TB/HIV coinfection the dolutegravir dose is doubled (given twice daily) during rifampicin-based TB treatment because of a drug-drug interaction (WHO TB Knowledge Sharing Platform).');
