    ('med_enalapril', 'hypertension', 'safe', 'Indicated antihypertensive.', 'Titrate 5-40 mg/day.', 'FDA label (enalapril maleate), Indications'),
    ('med_enalapril', 'diabetes', 'safe', 'Commonly used and renoprotective in diabetes.', 'Do not combine with aliskiren; diabetes increases hyperkalemia risk, so monitor potassium.', 'FDA label (enalapril maleate), Contraindications / Warnings'),
    ('med_enalapril', 'pregnant', 'avoid', 'Boxed warning: fetal toxicity (oligohydramnios, lung hypoplasia, skeletal malformations).', 'Discontinue as soon as pregnancy is detected.', 'FDA label (enalapril maleate), Boxed Warning'),
    ('med_enalapril', 'asthma', 'safe', 'No direct bronchoconstriction.', 'ACE-inhibitor cough can mimic poor asthma control; consider an ARB if cough develops.', 'FDA label (enalapril maleate), Warnings (cough)'),
    ('med_enalapril', 'peptic_ulcer', 'safe', 'No GI mucosal effect.', 'No adjustment needed.', 'FDA label (enalapril maleate)'),
    ('med_enalapril', 'renal_impairment', 'caution', 'Risk of hyperkalemia and creatinine rise; drug accumulates.', 'Start 2.5 mg daily if CrCl 30 mL/min or less; monitor creatinine and potassium.', 'FDA label (enalapril maleate), Dosage / Warnings'),
    ('med_enalapril', 'liver_disease', 'caution', 'Rare cholestatic jaundice progressing to fulminant hepatic necrosis; limited data in hepatic impairment.', 'Discontinue if jaundice or marked transaminase rise occurs.', 'FDA label (enalapril maleate), Warnings; StatPearls'),
    ('med_enalapril', 'autoimmune', 'caution', 'Neutropenia/agranulocytosis risk is higher in collagen vascular disease (SLE, scleroderma), especially with renal impairment.', 'Monitor white blood cell counts periodically.', 'FDA label (enalapril maleate), Warnings (neutropenia/agranulocytosis)'),
    ('med_hydrochlorothiazide', 'hypertension', 'safe', 'Indicated antihypertensive.', '12.5-25 mg daily usually sufficient.', 'FDA label (hydrochlorothiazide), Indications'),
    ('med_hydrochlorothiazide', 'diabetes', 'caution', 'Can cause hyperglycemia and unmask latent diabetes, partly via hypokalemia.', 'Monitor glucose; antidiabetic dose adjustment may be required.', 'FDA label (hydrochlorothiazide), Precautions; StatPearls'),
    ('med_hydrochlorothiazide', 'pregnant', 'caution', 'Crosses the placenta; not a preferred agent.', 'Labetalol and nifedipine are preferred for hypertension in pregnancy; HCTZ is an alternative.', 'StatPearls: Hydrochlorothiazide; FDA label (hydrochlorothiazide), Pregnancy'),
    ('med_hydrochlorothiazide', 'asthma', 'safe', 'No bronchoconstrictor effect.', 'Monitor potassium when combined with beta-2 agonists or systemic steroids.', 'FDA label (hydrochlorothiazide); Ventolin HFA label, Drug Interactions'),
    ('med_hydrochlorothiazide', 'peptic_ulcer', 'safe', 'No GI mucosal effect.', 'No adjustment needed.', 'FDA label (hydrochlorothiazide)'),
    ('med_hydrochlorothiazide', 'renal_impairment', 'caution', 'Contraindicated in anuria; ineffective in severe renal dysfunction and may precipitate azotemia.', 'Use cautiously in severe renal disease; loop diuretics are preferred when eGFR is very low.', 'FDA label (hydrochlorothiazide), Warnings; StatPearls'),
    ('med_hydrochlorothiazide', 'liver_disease', 'caution', 'Electrolyte shifts can precipitate hepatic coma in severe liver disease.', 'Use cautiously; monitor electrolytes.', 'FDA label (hydrochlorothiazide), Warnings'),
    ('med_hydrochlorothiazide', 'autoimmune', 'caution', 'Exacerbation or activation of systemic lupus erythematosus has been reported.', 'Use cautiously in SLE.', 'FDA label (hydrochlorothiazide), Warnings'),
    ('med_furosemide', 'hypertension', 'safe', 'Labeled for hypertension; preferred diuretic when GFR is low.', 'Monitor electrolytes and volume status.', 'FDA label (Lasix), Indications; StatPearls'),
    ('med_furosemide', 'diabetes', 'caution', 'Can raise blood glucose and precipitate diabetes.', 'Monitor glucose.', 'FDA label (Lasix), Precautions'),
    ('med_furosemide', 'pregnant', 'caution', 'Crosses the placenta; adverse effects in animal studies and no adequate human studies.', 'Use only if benefit justifies risk, with fetal monitoring.', 'FDA label (Lasix), Pregnancy; StatPearls'),
    ('med_furosemide', 'asthma', 'safe', 'No bronchoconstrictor effect.', 'Monitor potassium with concurrent beta-2 agonists or steroids.', 'FDA label (Lasix); Ventolin HFA label, Drug Interactions'),
    ('med_furosemide', 'peptic_ulcer', 'safe', 'No GI mucosal effect.', 'No adjustment needed.', 'FDA label (Lasix)'),
    ('med_furosemide', 'renal_impairment', 'caution', 'Contraindicated in anuria; higher doses are needed at low GFR and ototoxicity risk increases.', 'Discontinue if azotemia and oliguria increase during treatment of progressive renal disease.', 'FDA label (Lasix), Warnings; StatPearls'),
    ('med_furosemide', 'liver_disease', 'caution', 'Rapid fluid and electrolyte shifts can precipitate hepatic coma in cirrhosis.', 'Initiate in hospital in cirrhosis with ascites; avoid in hepatic coma until corrected.', 'FDA label (Lasix), Warnings'),
    ('med_furosemide', 'autoimmune', 'caution', 'May exacerbate or activate systemic lupus erythematosus.', 'Use cautiously in SLE.', 'FDA label (Lasix), Warnings'),
    ('med_spironolactone', 'hypertension', 'safe', 'Labeled for hypertension; key add-on for resistant hypertension.', 'Monitor potassium within 1 week and periodically.', 'FDA label (Aldactone), Indications'),
    ('med_spironolactone', 'diabetes', 'safe', 'No diabetes-specific restriction.', 'Monitor potassium closely when combined with ACE inhibitors or ARBs.', 'FDA label (Aldactone), Warnings (hyperkalemia)'),
    ('med_spironolactone', 'pregnant', 'avoid', 'Anti-androgenic effects may cause feminization of male fetuses (animal data).', 'Avoid spironolactone in pregnancy.', 'FDA label (Aldactone), Use in Specific Populations'),
    ('med_spironolactone', 'asthma', 'safe', 'No respiratory effect.', 'No adjustment needed.', 'FDA label (Aldactone)'),
    ('med_spironolactone', 'renal_impairment', 'caution', 'Markedly increased hyperkalemia risk; StatPearls lists eGFR <30 as a contraindication.', 'Avoid if eGFR <30 or hyperkalemia; otherwise monitor potassium and creatinine closely.', 'FDA label (Aldactone), Warnings; StatPearls'),
    ('med_spironolactone', 'liver_disease', 'caution', 'Fluid and electrolyte shifts can precipitate hepatic encephalopathy/coma, although it is used for cirrhotic ascites.', 'Initiate in hospital in cirrhosis and titrate slowly.', 'FDA label (Aldactone), Dosage / Warnings'),
    ('med_metoprolol', 'hypertension', 'safe', 'Indicated antihypertensive.', 'Taper rather than stop abruptly.', 'FDA label (Lopressor), Indications'),
    ('med_metoprolol', 'diabetes', 'caution', 'May mask hypoglycemia warning signs (tachycardia) and prolong hypoglycemia.', 'Monitor glucose more closely, especially with insulin or sulfonylureas.', 'FDA label (Lopressor), Warnings; StatPearls'),
    ('med_metoprolol', 'pregnant', 'caution', 'Crosses the placenta; neonatal bradycardia, hypotension and hypoglycemia possible.', 'Use if benefit outweighs risk; monitor neonate.', 'FDA label (Lopressor), Use in Specific Populations; StatPearls'),
    ('med_metoprolol', 'asthma', 'caution', 'Patients with bronchospastic disease should generally not receive beta-blockers; beta-1 selectivity is relative and lost at higher doses.', 'If used, give the lowest dose with a beta-2 agonist available.', 'FDA label (Lopressor), Warnings (bronchospastic disease)'),
    ('med_metoprolol', 'peptic_ulcer', 'safe', 'No GI mucosal effect.', 'No adjustment needed.', 'FDA label (Lopressor)'),
    ('med_metoprolol', 'renal_impairment', 'safe', 'Hepatically metabolized; no renal dose adjustment.', 'Standard dosing.', 'StatPearls: Metoprolol'),
    ('med_metoprolol', 'liver_disease', 'caution', 'Extensive hepatic (CYP2D6) metabolism; exposure increases.', 'Start at lower doses and titrate gradually.', 'FDA label (Lopressor), Warnings; StatPearls'),
    ('med_atorvastatin', 'hypertension', 'safe', 'No blood-pressure concern; reduces cardiovascular risk in hypertensive patients.', 'Standard dosing.', 'FDA label (Lipitor, 2024)'),
    ('med_atorvastatin', 'diabetes', 'safe', 'Strongly indicated for cardiovascular risk reduction in diabetes despite small increases in HbA1c/fasting glucose.', 'Monitor glycemia; benefits outweigh the modest glycemic effect.', 'FDA label (Lipitor, 2024), Warnings (5.4); StatPearls'),
    ('med_atorvastatin', 'pregnant', 'avoid', 'May cause fetal harm by decreasing cholesterol synthesis.', 'Discontinue when pregnancy is recognized (consider individual therapeutic need); breastfeeding not recommended.', 'FDA label (Lipitor, 2024), Use in Specific Populations (8.1, 8.2)'),
    ('med_atorvastatin', 'asthma', 'safe', 'No respiratory effect.', 'No adjustment needed.', 'FDA label (Lipitor, 2024)'),
    ('med_atorvastatin', 'peptic_ulcer', 'safe', 'No GI mucosal or bleeding effect.', 'No adjustment needed.', 'FDA label (Lipitor, 2024)'),
    ('med_atorvastatin', 'renal_impairment', 'caution', 'Renal impairment is a risk factor for myopathy, although no dose adjustment is needed.', 'Monitor for muscle symptoms.', 'FDA label (Lipitor, 2024), Use in Specific Populations (8.6)'),
    ('med_atorvastatin', 'liver_disease', 'avoid', 'Contraindicated in acute liver failure or decompensated cirrhosis; exposure rises markedly in chronic alcoholic liver disease.', 'Check liver enzymes before starting; use caution in chronic liver disease or heavy alcohol use.', 'FDA label (Lipitor, 2024), Contraindications / Warnings (5.3)'),
    ('med_atorvastatin', 'autoimmune', 'caution', 'Cyclosporine co-administration is not recommended; statins can rarely trigger immune-mediated necrotizing myopathy.', 'Avoid with cyclosporine; evaluate persistent weakness with CK.', 'FDA label (Lipitor, 2024), Drug Interactions / Warnings'),
    ('med_dapagliflozin', 'hypertension', 'safe', 'Modestly lowers blood pressure.', 'Watch for volume depletion with concurrent diuretics.', 'FDA label (Farxiga), Warnings; StatPearls'),
    ('med_dapagliflozin', 'diabetes', 'safe', 'Indicated for type 2 diabetes; not for type 1 diabetes because of ketoacidosis risk.', 'Reduce insulin/sulfonylurea dose if hypoglycemia; withhold before surgery or prolonged fasting.', 'FDA label (Farxiga), Indications / Warnings'),
    ('med_dapagliflozin', 'pregnant', 'avoid', 'Adverse renal effects in animal studies; not recommended in the second and third trimesters.', 'Switch to an alternative when pregnancy is detected; not recommended while breastfeeding.', 'FDA label (Farxiga), Use in Specific Populations'),
    ('med_dapagliflozin', 'asthma', 'safe', 'No respiratory effect.', 'No adjustment needed.', 'FDA label (Farxiga)'),
    ('med_dapagliflozin', 'peptic_ulcer', 'safe', 'No GI mucosal effect.', 'No adjustment needed.', 'FDA label (Farxiga)'),
    ('med_dapagliflozin', 'renal_impairment', 'caution', 'Glycemic efficacy falls at low eGFR, but kidney and heart benefits persist.', 'Not for glycemic control if eGFR <45; do not initiate if eGFR <25 (may continue); not studied when initiated on dialysis.', 'FDA label (Farxiga), Dosage and Administration'),
    ('med_dapagliflozin', 'liver_disease', 'caution', 'No adjustment in mild-to-moderate impairment; limited data in severe impairment.', 'Assess benefit-risk individually in severe hepatic impairment.', 'FDA label (Farxiga), Use in Specific Populations'),
    ('med_metformin', 'hypertension', 'safe', 'No blood-pressure concern.', 'Standard dosing.', 'FDA label (metformin)'),
    ('med_metformin', 'diabetes', 'safe', 'First-line therapy for type 2 diabetes.', 'Titrate gradually to limit GI effects; monitor B12 periodically.', 'FDA label (metformin), Indications; StatPearls'),
    ('med_metformin', 'pregnant', 'caution', 'Crosses the placenta; no clear association with birth defects, but insulin remains preferred.', 'May be used as an alternative to insulin in gestational/pregestational diabetes with specialist input.', 'FDA label (metformin), Pregnancy; StatPearls'),
    ('med_metformin', 'asthma', 'caution', 'Hypoxic states (e.g., severe acute asthma or COPD exacerbation) are a risk factor for lactic acidosis.', 'Stable disease is not a contraindication; withhold during acute hypoxemic illness.', 'FDA label (metformin), Boxed Warning (risk factors)'),
    ('med_metformin', 'peptic_ulcer', 'safe', 'GI adverse effects are functional, not ulcerogenic.', 'No adjustment needed.', 'FDA label (metformin)'),
    ('med_metformin', 'renal_impairment', 'caution', 'Renally excreted; accumulation increases lactic acidosis risk.', 'Contraindicated if eGFR <30; do not initiate at eGFR 30-45; check eGFR at least annually.', 'FDA label (metformin), Dosage / Contraindications'),
    ('med_metformin', 'liver_disease', 'avoid', 'Hepatic impairment reduces lactate clearance and increases lactic acidosis risk.', 'Label advises avoiding use in patients with clinical or laboratory evidence of hepatic disease.', 'FDA label (metformin), Warnings (lactic acidosis); StatPearls'),
    ('med_gliclazide', 'hypertension', 'safe', 'No blood-pressure effect.', 'ACE inhibitors may enhance hypoglycemia; monitor glucose.', 'UK SmPC (Diamicron MR), Interactions'),
    ('med_gliclazide', 'diabetes', 'safe', 'Indicated for type 2 diabetes; contraindicated in type 1 diabetes and ketoacidosis.', 'Regular meals needed; educate on hypoglycemia.', 'UK SmPC (Diamicron MR), Indications / Contraindications'),
    ('med_gliclazide', 'pregnant', 'avoid', 'Insulin is preferred; oral sulfonylureas should be switched when pregnancy is planned or detected.', 'Contraindicated in breastfeeding (neonatal hypoglycemia risk).', 'UK SmPC (Diamicron MR), Fertility, pregnancy and lactation'),
    ('med_gliclazide', 'asthma', 'safe', 'No respiratory effect.', 'Systemic corticosteroids for exacerbations raise glucose; monitor.', 'UK SmPC (Diamicron MR), Interactions'),
    ('med_gliclazide', 'renal_impairment', 'caution', 'Altered pharmacokinetics prolong hypoglycemia; contraindicated in severe renal insufficiency.', 'Use with close glucose monitoring in mild-to-moderate impairment; avoid in severe.', 'UK SmPC (Diamicron MR), Contraindications / Warnings'),
    ('med_gliclazide', 'liver_disease', 'caution', 'Reduced metabolism prolongs hypoglycemia; contraindicated in severe hepatic insufficiency.', 'Avoid in severe impairment; monitor closely otherwise.', 'UK SmPC (Diamicron MR), Contraindications / Warnings'),
    ('med_salbutamol', 'hypertension', 'caution', 'May raise pulse and blood pressure and cause ECG changes.', 'Use cautiously in hypertension, coronary insufficiency or arrhythmias.', 'FDA label (Ventolin HFA), Warnings (cardiovascular effects)'),
    ('med_salbutamol', 'diabetes', 'caution', 'Beta-2 agonists can raise glucose; high-dose IV albuterol may aggravate diabetes and ketoacidosis.', 'Monitor glucose with frequent or high-dose use.', 'FDA label (Ventolin HFA), Warnings; StatPearls'),
    ('med_salbutamol', 'pregnant', 'safe', 'Well-controlled asthma protects mother and fetus; albuterol is standard for acute symptoms and exacerbations.', 'Human safety data are limited; use at the lowest effective frequency with close asthma monitoring.', 'StatPearls: Albuterol; FDA label (Ventolin HFA), Pregnancy'),
    ('med_salbutamol', 'asthma', 'safe', 'Indicated reliever for asthma and COPD.', 'Rising reliever use signals poor control needing anti-inflammatory therapy.', 'FDA label (Ventolin HFA), Indications / Warnings'),
    ('med_salbutamol', 'peptic_ulcer', 'safe', 'No GI mucosal effect.', 'No adjustment needed.', 'FDA label (Ventolin HFA)'),
    ('med_budesonide_formoterol', 'hypertension', 'caution', 'Formoterol can increase pulse and blood pressure and cause arrhythmias.', 'Use cautiously in cardiovascular disease and hypertension.', 'FDA label (Symbicort), Warnings (cardiovascular effects)'),
    ('med_budesonide_formoterol', 'diabetes', 'caution', 'Beta-agonist and corticosteroid components can raise blood glucose.', 'Monitor glucose, particularly at high doses.', 'FDA label (Symbicort), Warnings (hyperglycemia)'),
    ('med_budesonide_formoterol', 'pregnant', 'safe', 'Controlling asthma in pregnancy outweighs drug risk; budesonide is the inhaled corticosteroid with the most human pregnancy data.', 'Continue maintenance therapy at the lowest effective dose.', 'FDA label (Symbicort), Use in Specific Populations; GINA'),
    ('med_budesonide_formoterol', 'asthma', 'safe', 'Indicated for asthma and COPD maintenance.', 'Not a substitute for a reliever for acute bronchospasm under US labeling.', 'FDA label (Symbicort), Indications'),
    ('med_budesonide_formoterol', 'peptic_ulcer', 'safe', 'Low systemic exposure at usual inhaled doses.', 'No adjustment needed.', 'FDA label (Symbicort)'),
    ('med_budesonide_formoterol', 'liver_disease', 'caution', 'Both components are hepatically metabolized; exposure may increase in hepatic impairment.', 'Monitor for systemic corticosteroid effects.', 'FDA label (Symbicort), Warnings (hepatic impairment)'),
    ('med_budesonide_formoterol', 'autoimmune', 'caution', 'Corticosteroids can increase infection risk; additive immunosuppression with systemic immunosuppressants is possible.', 'Monitor for infections and oral candidiasis.', 'FDA label (Symbicort), Warnings (immunosuppression)'),
    ('med_prednisone', 'hypertension', 'caution', 'Causes sodium and water retention and elevated blood pressure.', 'Monitor blood pressure; use the lowest effective dose and duration.', 'FDA label (prednisone tablets), Warnings (cardio-renal)'),
    ('med_prednisone', 'diabetes', 'caution', 'Raises blood glucose and can unmask diabetes.', 'Monitor glucose; antidiabetic dose adjustment may be required.', 'FDA label (prednisone tablets), Warnings (endocrine)'),
    ('med_prednisone', 'pregnant', 'caution', 'Teratogenic in animal studies; human benefit often outweighs risk for serious maternal disease.', 'Use only if benefit justifies risk; monitor neonate for hypoadrenalism after high-dose use.', 'FDA label (prednisone tablets), Pregnancy'),
    ('med_prednisone', 'asthma', 'safe', 'Indicated for asthma exacerbations and severe asthma.', 'Use short courses where possible; long-term oral use carries systemic toxicity.', 'FDA label (prednisone tablets), Indications (allergic states)'),
    ('med_prednisone', 'peptic_ulcer', 'caution', 'Use with caution in active or latent peptic ulcer; increased perforation risk, especially with NSAIDs.', 'Avoid concomitant NSAIDs; consider gastroprotection.', 'FDA label (prednisone tablets), Warnings (gastrointestinal)'),
    ('med_prednisone', 'renal_impairment', 'caution', 'Fluid retention and electrolyte disturbance.', 'Use cautiously in renal insufficiency; monitor fluid and electrolytes.', 'FDA label (prednisone tablets), Warnings (cardio-renal)'),
    ('med_prednisone', 'liver_disease', 'caution', 'Enhanced corticosteroid effect in cirrhosis; hepatitis B reactivation possible with immunosuppression.', 'Screen for hepatitis B before prolonged therapy; use lowest effective dose.', 'FDA label (prednisone tablets), Precautions'),
    ('med_prednisone', 'autoimmune', 'caution', 'Indicated for many autoimmune diseases, but adds to immunosuppression and infection risk with biologics/DMARDs.', 'Screen for latent TB/hepatitis B; avoid live vaccines at immunosuppressive doses.', 'FDA label (prednisone tablets), Indications / Warnings (infections, vaccines)'),
    ('med_sumatriptan', 'hypertension', 'caution', 'Contraindicated in uncontrolled hypertension; can raise blood pressure, including hypertensive crisis.', 'Avoid if uncontrolled; in controlled hypertension monitor blood pressure and assess cardiovascular risk.', 'FDA label (Imitrex tablets), Contraindications / Warnings'),
    ('med_sumatriptan', 'diabetes', 'caution', 'Diabetes is a cardiovascular risk factor; triptans can cause myocardial ischemia.', 'Cardiovascular evaluation is advised in triptan-naive patients with multiple risk factors.', 'FDA label (Imitrex tablets), Warnings (myocardial ischemia)'),
    ('med_sumatriptan', 'pregnant', 'caution', 'Human registry data show no increase in major birth defects; animal studies showed embryolethality.', 'Use if clinically needed; avoid breastfeeding for 12 hours after a dose to minimize infant exposure.', 'FDA label (Imitrex tablets), Use in Specific Populations'),
    ('med_sumatriptan', 'asthma', 'safe', 'No bronchoconstrictor effect or respiratory contraindication.', 'No adjustment needed.', 'FDA label (Imitrex tablets)'),
    ('med_sumatriptan', 'liver_disease', 'caution', 'Exposure increases with hepatic impairment; contraindicated in severe impairment.', 'Maximum single oral dose 50 mg in mild-to-moderate impairment; avoid in severe.', 'FDA label (Imitrex tablets), Dosage / Contraindications'),
    ('med_tenofovir', 'hypertension', 'safe', 'No hypertension-specific precaution in labeling.', 'Standard dosing; renal function monitoring as for all patients.', 'VIREAD FDA label'),
    ('med_tenofovir', 'diabetes', 'safe', 'No diabetes-specific precaution in labeling.', 'Label renal monitoring includes urine glucose; results are interpreted alongside the patient''s glycemic status.', 'VIREAD FDA label, Warnings (Renal impairment)'),
    ('med_tenofovir', 'pregnant', 'safe', 'Antiretroviral Pregnancy Registry data show no increase in overall major birth defects with first-trimester TDF exposure (2.1%); TDF is used to reduce hepatitis B mother-to-child transmission.', 'Continue or start when indicated; in HIV-1 infection breastfeeding is not recommended to avoid postnatal transmission.', 'VIREAD FDA label, 8.1-8.2; StatPearls: Hepatitis B'),
    ('med_tenofovir', 'asthma', 'safe', 'No asthma-specific precaution in labeling.', 'Standard dosing.', 'VIREAD FDA label'),
    ('med_tenofovir', 'peptic_ulcer', 'safe', 'No GI-bleeding precaution in labeling; note that high-dose or multiple NSAIDs are avoided with TDF for renal reasons.', 'Standard dosing.', 'VIREAD FDA label, Warnings (Renal impairment)'),
    ('med_tenofovir', 'renal_impairment', 'caution', 'Tenofovir is renally eliminated and nephrotoxic (acute renal failure, Fanconi syndrome); exposure rises as CrCl falls.', 'Extend the dosing interval when CrCl < 50 mL/min (every 48 h at 30-49; every 72-96 h at 10-29; every 7 days on hemodialysis); no recommendation for CrCl < 10 mL/min without dialysis; monitor creatinine, urine protein/glucose and phosphorus; avoid nephrotoxic co-medication.', 'VIREAD FDA label, Dosage (Table 3) and Warnings 5.2'),
    ('med_tenofovir', 'liver_disease', 'caution', 'No dose change is needed in hepatic impairment, but stopping therapy in hepatitis B can trigger severe acute hepatitis flares; lactic acidosis with hepatomegaly and steatosis is a class warning.', 'Do not stop without a plan; monitor hepatic function closely for several months after discontinuation in HBV infection.', 'VIREAD FDA label, Boxed warning and 8.x Hepatic impairment'),
    ('med_tenofovir', 'autoimmune', 'safe', 'No autoimmune-specific contraindication; autoimmune disorders (e.g., Graves'' disease, polymyositis, Guillain-Barre syndrome) have been reported during immune reconstitution in HIV.', 'Standard dosing; watch for immune reconstitution phenomena after starting antiretroviral therapy.', 'VIREAD FDA label, Warnings (Immune reconstitution syndrome)'),
    ('med_entecavir', 'hypertension', 'safe', 'No hypertension-specific precaution in labeling.', 'Standard dosing.', 'BARACLUDE FDA label'),
    ('med_entecavir', 'diabetes', 'safe', 'No diabetes-specific precaution in labeling.', 'Standard dosing.', 'BARACLUDE FDA label'),
    ('med_entecavir', 'pregnant', 'caution', 'Human pregnancy exposures are too few for a risk assessment; animal studies showed no adverse effects at relevant exposures. Tenofovir has published evidence for reducing mother-to-child HBV transmission.', 'Use when the benefit justifies the risk; tenofovir disoproxil is the agent with pregnancy data for HBV.', 'BARACLUDE FDA label, 8.1; StatPearls: Hepatitis B'),
    ('med_entecavir', 'asthma', 'safe', 'No asthma-specific precaution in labeling.', 'Standard dosing.', 'BARACLUDE FDA label'),
    ('med_entecavir', 'peptic_ulcer', 'safe', 'No GI-bleeding precaution in labeling.', 'Standard dosing on an empty stomach.', 'BARACLUDE FDA label'),
    ('med_entecavir', 'renal_impairment', 'caution', 'Entecavir is renally eliminated; exposure increases as creatinine clearance falls.', 'Reduce the daily dose or extend the interval when CrCl < 50 mL/min per the label table; give after hemodialysis.', 'BARACLUDE FDA label, Dosage (Table 2)'),
    ('med_entecavir', 'liver_disease', 'caution', 'Indicated in chronic hepatitis B including decompensated disease (1 mg) with no hepatic dose adjustment, but lactic acidosis is a nucleoside-analogue warning and stopping therapy can cause severe hepatitis flares.', 'Monitor hepatic function closely during and for several months after stopping; suspend if lactic acidosis or pronounced hepatotoxicity develops.', 'BARACLUDE FDA label, Boxed warning and Warnings'),
    ('med_entecavir', 'autoimmune', 'safe', 'No autoimmune-specific precaution in labeling.', 'Standard dosing; in transplant recipients on cyclosporine or tacrolimus, monitor renal function.', 'BARACLUDE FDA label, 8.8'),
    ('med_tld', 'hypertension', 'safe', 'No hypertension-specific precaution in the product information.', 'Standard dosing; routine renal monitoring for the tenofovir component.', 'WHOPAR SmPC (HA729)'),
    ('med_tld', 'diabetes', 'caution', 'Dolutegravir increases metformin exposure; integrase inhibitors are also associated with weight gain.', 'When starting or stopping TLD in a patient on metformin, consider metformin dose adjustment and monitor glycemic control and metformin adverse effects.', 'WHOPAR SmPC (HA729) Interactions; NIH ARV Guidelines INSTI interaction table; StatPearls: HIV and AIDS'),
    ('med_tld', 'pregnant', 'safe', 'WHO recommends dolutegravir as the preferred regimen in all populations, including pregnant women; the early neural tube defect signal was lower in larger studies, and a large US cohort did not find increased risk.', 'The product information advises informing women in the first trimester of a possible small increased neural tube defect risk; dolutegravir may be used in the second and third trimester when benefit justifies risk.', 'WHO news release 22 July 2019; WHOPAR SmPC (HA729) 4.6; StatPearls: HIV and AIDS'),
    ('med_tld', 'asthma', 'safe', 'No asthma-specific precaution in the product information.', 'Standard dosing.', 'WHOPAR SmPC (HA729)'),
    ('med_tld', 'peptic_ulcer', 'safe', 'No GI-bleeding precaution in the product information; aluminium/magnesium antacids and sucralfate reduce dolutegravir absorption.', 'Give TLD 2 hours before or 6 hours after polyvalent-cation antacids or sucralfate.', 'WHOPAR SmPC (HA729); TIVICAY FDA label'),
    ('med_tld', 'renal_impairment', 'avoid', 'The fixed-dose combination cannot be dose-adjusted; tenofovir disoproxil is nephrotoxic and lamivudine and tenofovir require interval or dose changes when CrCl falls.', 'Not recommended if CrCl < 50 mL/min; use separate component formulations with appropriate adjustment. Interrupt if CrCl falls below 50 mL/min during therapy.', 'WHOPAR SmPC (HA729) Posology and Warnings'),
    ('med_tld', 'liver_disease', 'caution', 'No adjustment in mild or moderate hepatic impairment; no safety data in severe impairment. Stopping therapy in HBV coinfection can cause hepatitis flares; dolutegravir hypersensitivity can involve the liver.', 'Use with caution in severe hepatic impairment; monitor closely for hepatitis exacerbation for at least 6 months after discontinuation in HBV coinfection.', 'WHOPAR SmPC (HA729)'),
    ('med_tld', 'autoimmune', 'safe', 'No autoimmune-specific contraindication; autoimmune disorders (e.g., Graves'' disease) have been reported during immune reconstitution after starting antiretroviral therapy.', 'Standard dosing; watch for immune reconstitution phenomena.', 'VIREAD (tenofovir disoproxil) FDA label, Warnings (Immune reconstitution syndrome)'),
    ('med_cotrimoxazole', 'hypertension', 'caution', 'Trimethoprim causes dose-related hyperkalemia; risk is greater with ACE inhibitors, ARBs or potassium-sparing diuretics commonly used in hypertension.', 'Check potassium and renal function during therapy, particularly with RAAS blockers or spironolactone; the label advises avoiding concurrent ACE inhibitor use.', 'BACTRIM FDA label, Warnings (Hyperkalemia) and Drug Interactions; StatPearls: Trimethoprim-Sulfamethoxazole'),
    ('med_cotrimoxazole', 'diabetes', 'caution', 'Potentiates sulfonylureas and can rarely cause hypoglycemia, especially with renal dysfunction or high doses.', 'Monitor blood glucose in patients on sulfonylureas or other oral hypoglycemics.', 'BACTRIM FDA label, Warnings (Hypoglycemia) and Drug Interactions'),
    ('med_cotrimoxazole', 'pregnant', 'caution', 'Folate antagonism; early-pregnancy exposure has been associated with neural tube defects, cardiovascular malformations and oral clefts. Sulfonamides can displace bilirubin (kernicterus risk in vulnerable infants).', 'Use during pregnancy only if the potential benefit justifies the potential risk to the fetus.', 'BACTRIM FDA label, Pregnancy and Nursing mothers; StatPearls: Trimethoprim-Sulfamethoxazole'),
    ('med_cotrimoxazole', 'asthma', 'caution', 'The label lists severe allergies and bronchial asthma among conditions in which use is to be avoided because of hypersensitivity risk.', 'Consider alternatives in severe allergy or asthma; if used, monitor for hypersensitivity reactions.', 'BACTRIM FDA label, Precautions (General)'),
    ('med_cotrimoxazole', 'peptic_ulcer', 'safe', 'No GI-bleeding precaution in labeling.', 'Standard dosing.', 'BACTRIM FDA label'),
    ('med_cotrimoxazole', 'renal_impairment', 'caution', 'Both components are renally cleared; renal impairment increases the risk of hyperkalemia, crystalluria, hypoglycemia and further kidney injury.', 'Usual dose if CrCl > 30 mL/min; half the usual regimen at 15-30 mL/min; not recommended below 15 mL/min. Monitor renal function and potassium; contraindicated in severe renal insufficiency when renal function cannot be monitored.', 'BACTRIM FDA label, Dosage (Renal impairment) and Contraindications'),
    ('med_cotrimoxazole', 'liver_disease', 'avoid', 'Contraindicated in marked hepatic damage; fulminant hepatic necrosis has occurred with sulfamethoxazole-trimethoprim.', 'Avoid in significant hepatic impairment; discontinue at the first sign of hepatotoxicity.', 'BACTRIM FDA label, Contraindications and Warnings'),
    ('med_cotrimoxazole', 'autoimmune', 'caution', 'Concurrent methotrexate (used in rheumatoid arthritis and other autoimmune diseases) increases the risk of marrow suppression; immunosuppressed and AIDS patients have higher adverse-reaction rates.', 'Avoid co-prescription with methotrexate; monitor CBC in immunosuppressed patients.', 'BACTRIM FDA label, Drug Interactions and Warnings'),
    ('med_praziquantel', 'hypertension', 'safe', 'No hypertension-specific precaution in labeling.', 'Standard dosing.', 'BILTRICIDE FDA label'),
    ('med_praziquantel', 'diabetes', 'safe', 'No diabetes-specific precaution in labeling.', 'Standard dosing.', 'BILTRICIDE FDA label'),
    ('med_praziquantel', 'pregnant', 'caution', 'Published studies have not identified an association with major birth defects, miscarriage or adverse maternal or fetal outcomes, and randomized trials in pregnant women with schistosomiasis have been reported; older reviews advised avoiding use in pregnancy.', 'Use when treatment is indicated after weighing benefit and risk; praziquantel is present in human milk at low concentrations.', 'BILTRICIDE FDA label, 8.1-8.2; StatPearls: Antiparasitic Drugs'),
    ('med_praziquantel', 'asthma', 'safe', 'No asthma-specific precaution in labeling.', 'Standard dosing.', 'BILTRICIDE FDA label'),
    ('med_praziquantel', 'peptic_ulcer', 'safe', 'Abdominal discomfort is common, but there is no GI-bleeding precaution in labeling.', 'Standard dosing.', 'BILTRICIDE FDA label'),
    ('med_praziquantel', 'renal_impairment', 'safe', 'No dosage adjustment is necessary in renal impairment.', 'Standard dosing.', 'BILTRICIDE FDA label, 8.7'),
    ('med_praziquantel', 'liver_disease', 'caution', 'Hepatic impairment produces higher and sustained plasma concentrations; patients with hepatosplenic schistosomiasis often have moderate or severe impairment.', 'Give the recommended dose to patients with Child-Pugh B or C impairment with monitoring for adverse reactions.', 'BILTRICIDE FDA label, 8.6'),
    ('med_praziquantel', 'autoimmune', 'safe', 'No autoimmune-specific precaution in labeling.', 'Standard dosing; check co-medications for CYP3A inducers or inhibitors.', 'BILTRICIDE FDA label'),
    ('med_aciclovir', 'hypertension', 'safe', 'No hypertension-specific precaution in labeling.', 'Standard dosing.', 'Acyclovir FDA label'),
    ('med_aciclovir', 'diabetes', 'safe', 'No diabetes-specific precaution in labeling.', 'Standard dosing; adjust for any diabetic kidney disease.', 'Acyclovir FDA label'),
    ('med_aciclovir', 'pregnant', 'caution', 'Aciclovir crosses the placenta; registry data from first-trimester exposures showed birth-defect rates similar to the general population, but data are limited.', 'Use during pregnancy only if the potential benefit justifies the potential risk; compatible with breastfeeding per StatPearls.', 'Acyclovir FDA label, Pregnancy; StatPearls: Acyclovir'),
    ('med_aciclovir', 'asthma', 'safe', 'No asthma-specific precaution in labeling.', 'Standard dosing.', 'Acyclovir FDA label'),
    ('med_aciclovir', 'peptic_ulcer', 'safe', 'No GI-bleeding precaution in labeling.', 'Standard dosing.', 'Acyclovir FDA label'),
    ('med_aciclovir', 'renal_impairment', 'caution', 'Renal impairment can increase the half-life of aciclovir up to about 10-fold; renal failure (sometimes fatal) and neurotoxicity are more likely.', 'Reduce frequency per the label table based on CrCl; maintain hydration; monitor renal function and mental status, especially with IV therapy.', 'Acyclovir FDA label, Dosage (Renal impairment) and Warnings; StatPearls: Acyclovir'),
    ('med_aciclovir', 'liver_disease', 'safe', 'Aciclovir is eliminated mainly by the kidneys; the label focuses dose adjustment on renal function.', 'Standard dosing.', 'Acyclovir FDA label; StatPearls: Acyclovir'),
    ('med_aciclovir', 'autoimmune', 'caution', 'TTP/HUS, which can be fatal, has occurred in immunocompromised patients receiving aciclovir.', 'Monitor blood counts and renal function in immunosuppressed patients.', 'Acyclovir FDA label, Warnings'),
    ('med_rabies_vaccine', 'hypertension', 'safe', 'No hypertension-specific precaution.', 'Standard PEP schedule.', 'RABAVERT FDA label'),
    ('med_rabies_vaccine', 'diabetes', 'safe', 'No diabetes-specific precaution.', 'Standard PEP schedule.', 'RABAVERT FDA label'),
    ('med_rabies_vaccine', 'pregnant', 'safe', 'Pregnancy is not a contraindication to post-exposure prophylaxis; limited data show no increase in fetal anomalies.', 'Give full PEP when indicated; the label reserves pre-exposure vaccination in pregnancy for clear need.', 'RABAVERT FDA label, Contraindications and Pregnancy; StatPearls: Rabies'),
    ('med_rabies_vaccine', 'asthma', 'safe', 'No asthma-specific precaution.', 'Standard PEP schedule; epinephrine available as for all vaccinations.', 'RABAVERT FDA label'),
    ('med_rabies_vaccine', 'peptic_ulcer', 'safe', 'No GI precaution.', 'Standard PEP schedule.', 'RABAVERT FDA label'),
    ('med_rabies_vaccine', 'renal_impairment', 'safe', 'No renal-specific precaution.', 'Standard PEP schedule.', 'RABAVERT FDA label'),
    ('med_rabies_vaccine', 'liver_disease', 'safe', 'No hepatic-specific precaution.', 'Standard PEP schedule.', 'RABAVERT FDA label'),
    ('med_rabies_vaccine', 'autoimmune', 'caution', 'Corticosteroids and other immunosuppressive agents can impair the immune response to the vaccine.', 'Do not withhold PEP; immunocompromised persons receive the fuller schedule (e.g., a fifth dose on day 28 per CDC) and immunoglobulin, and serologic testing is recommended to confirm an adequate antibody response.', 'RABAVERT FDA label, Drug Interactions; StatPearls: Rabies'),
    ('med_rabies_immunoglobulin', 'hypertension', 'safe', 'No hypertension-specific precaution.', 'Standard dosing.', 'HYPERRAB FDA label'),
    ('med_rabies_immunoglobulin', 'diabetes', 'safe', 'No diabetes-specific precaution.', 'Standard dosing.', 'HYPERRAB FDA label'),
    ('med_rabies_immunoglobulin', 'pregnant', 'safe', 'Human pregnancy data are lacking for HRIG, but post-exposure prophylaxis is not contraindicated in pregnancy because rabies is nearly always fatal.', 'Give when a category III exposure calls for it; the label advises use only if clearly needed.', 'HYPERRAB FDA label, 8.1; RABAVERT FDA label, Contraindications'),
    ('med_rabies_immunoglobulin', 'asthma', 'safe', 'No asthma-specific precaution; hypersensitivity reactions can occur with any immunoglobulin.', 'Observe after administration with epinephrine available.', 'HYPERRAB FDA label, Warnings'),
    ('med_rabies_immunoglobulin', 'peptic_ulcer', 'safe', 'No GI precaution.', 'Standard dosing.', 'HYPERRAB FDA label'),
    ('med_rabies_immunoglobulin', 'renal_impairment', 'safe', 'No renal-specific precaution in labeling.', 'Standard weight-based dose.', 'HYPERRAB FDA label'),
    ('med_rabies_immunoglobulin', 'liver_disease', 'safe', 'No hepatic-specific precaution in labeling.', 'Standard weight-based dose.', 'HYPERRAB FDA label'),
    ('med_rabies_immunoglobulin', 'autoimmune', 'safe', 'No autoimmune-specific precaution; immunosuppressed persons need immunoglobulin plus vaccine even with prior vaccination.', 'Give with vaccine for category III exposures; confirm vaccine response serologically if immunosuppressed.', 'StatPearls: Rabies; HYPERRAB FDA label'),
    ('med_cetirizine', 'hypertension', 'safe', 'No hypertension-specific precaution in the Drug Facts label (unlike decongestant combinations).', 'Standard dosing; check that combination products do not contain a decongestant.', 'ZYRTEC ALLERGY Drug Facts label'),
    ('med_cetirizine', 'diabetes', 'safe', 'No diabetes-specific precaution in labeling.', 'Standard dosing.', 'ZYRTEC ALLERGY Drug Facts label'),
    ('med_cetirizine', 'pregnant', 'safe', 'Former FDA category B; ACOG-ACAAI recommend cetirizine for pregnant women who need an antihistamine.', 'Use when needed after consulting a health professional (per OTC label); OTC labeling does not recommend use while breastfeeding.', 'StatPearls: Cetirizine; ZYRTEC ALLERGY Drug Facts label'),
    ('med_cetirizine', 'asthma', 'safe', 'No asthma-specific precaution in labeling.', 'Standard dosing.', 'ZYRTEC ALLERGY Drug Facts label; StatPearls: Cetirizine'),
    ('med_cetirizine', 'peptic_ulcer', 'safe', 'No GI precaution in labeling.', 'Standard dosing.', 'ZYRTEC ALLERGY Drug Facts label'),
    ('med_cetirizine', 'renal_impairment', 'caution', 'Dose reduction is recommended in moderate-to-severe renal impairment.', '5 mg once daily when CrCl is 11-31 mL/min; OTC label directs patients with kidney disease to ask a doctor.', 'StatPearls: Cetirizine; ZYRTEC ALLERGY Drug Facts label'),
    ('med_cetirizine', 'liver_disease', 'caution', 'Dose reduction is recommended in hepatic impairment.', '5 mg once daily in hepatic impairment; OTC label directs patients with liver disease to ask a doctor.', 'StatPearls: Cetirizine; ZYRTEC ALLERGY Drug Facts label'),
    ('med_cetirizine', 'autoimmune', 'safe', 'No autoimmune-specific precaution in labeling.', 'Standard dosing.', 'ZYRTEC ALLERGY Drug Facts label'),
    ('med_zinc_sulfate', 'hypertension', 'safe', 'No hypertension-specific precaution; thiazide diuretics increase urinary zinc loss.', 'Standard dosing within the upper intake level.', 'NIH ODS Zinc fact sheet'),
    ('med_zinc_sulfate', 'diabetes', 'safe', 'No diabetes-specific precaution in product information.', 'Standard dosing within the upper intake level.', 'WHOPAR SmPC (DI005)'),
    ('med_zinc_sulfate', 'pregnant', 'safe', 'Requirement rises to 11 mg/day in pregnancy; pregnancy data for therapeutic courses are sparse and use may be considered if necessary.', 'Keep intake at or below 40 mg/day elemental zinc in well-nourished pregnant or lactating women.', 'StatPearls: Zinc; WHOPAR SmPC (DI005) 4.6'),
    ('med_zinc_sulfate', 'asthma', 'safe', 'No asthma-specific precaution.', 'Standard dosing.', 'WHOPAR SmPC (DI005)'),
    ('med_zinc_sulfate', 'peptic_ulcer', 'caution', 'Zinc salts commonly cause nausea, vomiting, epigastric pain and dyspepsia; overdose causes GI irritation and ulceration.', 'Use the recommended dose and duration; avoid excess dosing.', 'WHOPAR SmPC (DI005) Undesirable effects and Overdose; StatPearls: Zinc'),
    ('med_zinc_sulfate', 'renal_impairment', 'caution', 'No renal dose guidance in the product information; overdose can cause acute renal injury.', 'Avoid exceeding recommended doses; use therapeutic courses only as indicated.', 'WHOPAR SmPC (DI005) Overdose'),
    ('med_zinc_sulfate', 'liver_disease', 'safe', 'No hepatic-specific precaution in product information; zinc salts are used in Wilson disease.', 'Standard dosing within the upper intake level.', 'StatPearls: Zinc; WHOPAR SmPC (DI005)'),
    ('med_zinc_sulfate', 'autoimmune', 'safe', 'No autoimmune-specific precaution; zinc reduces the absorption of penicillamine used in rheumatoid arthritis.', 'Separate zinc from penicillamine doses.', 'NIH ODS Zinc fact sheet');
INSERT INTO public.drug_interactions (medicine_a_id, medicine_b_id, severity, description, clinical_significance, recommendation, source_attribution, is_published) VALUES
    ('med_aspirin', 'med_warfarin', 'avoid', 'Aspirin inhibits platelet aggregation and irritates the gastric mucosa, adding a pharmacodynamic bleeding effect to warfarin anticoagulation; salicylates can also increase free warfarin.', 'Combined anticoagulant and antiplatelet effect is associated with a substantially higher risk of major and gastrointestinal bleeding.', 'Combination generally avoided unless a specific indication exists (e.g., certain mechanical valves or recent coronary stenting); if used, monitor closely for bleeding and consider gastroprotection.', 'Warfarin sodium tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0cbce382-9c88-4f58-ae0f-532a841e8f95)', true),
    ('med_ibuprofen', 'med_warfarin', 'avoid', 'NSAIDs inhibit platelet function and injure the GI mucosa; the effects of warfarin and NSAIDs on GI bleeding are synergistic.', 'Users of both drugs have a risk of serious GI bleeding higher than users of either drug alone.', 'Avoid combination; paracetamol is the usual analgesic alternative. If unavoidable, use lowest dose for shortest time and monitor for bleeding.', 'Ibuprofen tablets, FDA label (DailyMed), Drug Interactions / Warnings (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=888a5dbc-9464-e272-e053-2a95a90ad687)', true),
    ('med_mefenamic_acid', 'med_warfarin', 'avoid', 'Mefenamic acid, like other NSAIDs, impairs platelet function and damages the GI mucosa, adding to warfarin''s anticoagulant effect.', 'Synergistic increase in risk of serious gastrointestinal bleeding.', 'Avoid combination; if unavoidable, monitor INR and for signs of bleeding (label: monitor patients using mefenamic acid with anticoagulants such as warfarin).', 'Mefenamic acid capsules, FDA label (DailyMed), Section 7.1 (Table 1) (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=4b0788cd-bdca-4fa5-9eba-01a270613aab)', true),
    ('med_clopidogrel', 'med_warfarin', 'avoid', 'Clopidogrel inhibits P2Y12-mediated platelet aggregation; combined with warfarin there are independent effects on hemostasis.', 'Coadministration increases the risk of bleeding.', 'Avoid unless specifically indicated (e.g., limited-duration therapy after coronary stenting in atrial fibrillation); if used, monitor closely for bleeding.', 'PLAVIX (clopidogrel), FDA label (DailyMed), Sections 5 and 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=de8b0b67-eb25-4684-83b5-7ad785314227)', true),
    ('med_ciprofloxacin', 'med_warfarin', 'caution', 'Ciprofloxacin inhibits CYP1A2 and CYP3A4, reducing metabolism of warfarin (R-enantiomer) and increasing its anticoagulant effect.', 'INR elevation and bleeding may occur during and shortly after the antibiotic course.', 'Monitor prothrombin time/INR frequently during and shortly after coadministration; adjust warfarin dose as needed.', 'Ciprofloxacin tablets, FDA label (DailyMed), Boxed Warning, Section 5 and Section 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5f4e80a1-0225-63dd-e053-2991aa0aa7fb)', true),
    ('med_clarithromycin', 'med_warfarin', 'caution', 'Clarithromycin is a strong CYP3A4 inhibitor (listed in the warfarin label), reducing warfarin clearance.', 'Risk of serious hemorrhage and significant elevations in INR and prothrombin time.', 'Monitor INR frequently when starting or stopping clarithromycin; consider an alternative antibiotic.', 'Clarithromycin tablets, FDA label (DailyMed), Warnings and Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b98b02bb-2609-49a0-b29f-e5911aa0cbc1)', true),
    ('med_rifampicin', 'med_warfarin', 'avoid', 'Rifampicin strongly induces CYP2C9, CYP1A2 and CYP3A4, markedly increasing warfarin metabolism and reducing its anticoagulant effect.', 'Loss of anticoagulation (sub-therapeutic INR) with risk of thrombosis; large warfarin dose increases may be required, with over-anticoagulation after rifampicin is stopped.', 'Avoid if possible; if unavoidable, perform prothrombin time/INR daily or as frequently as necessary and adjust warfarin dose, including after rifampicin is stopped.', 'RIFADIN (rifampin), FDA label (DailyMed), Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=036ab68e-5085-4edc-bd83-784b43d64eab&type=display)', true),
    ('med_nirmatrelvir_ritonavir', 'med_warfarin', 'caution', 'Ritonavir can alter warfarin concentrations in either direction (inhibition of CYP3A4 and induction of CYP2C9/CYP1A2).', 'Unpredictable change in INR during and after the 5-day course.', 'Closely monitor INR if coadministration with warfarin is necessary.', 'PAXLOVID (nirmatrelvir; ritonavir), FDA label (DailyMed), Sections 4 and 7 (Table 2) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8a99d6d6-fd9e-45bb-b1bf-48c7f761232a)', true),
    ('med_omeprazole', 'med_warfarin', 'caution', 'Omeprazole may alter warfarin metabolism (CYP2C19 inhibition affecting R-warfarin).', 'Increased INR and prothrombin time have been reported in patients receiving PPIs, including omeprazole, with warfarin.', 'Monitor INR when omeprazole is started or stopped.', 'Omeprazole delayed-release capsules, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=5aba19da-663f-4901-94e2-f438dba4841f&type=display)', true),
    ('med_prednisone', 'med_warfarin', 'caution', 'Prednisone is listed as a CYP3A4 inducer in the warfarin label; corticosteroids may also alter warfarin response and increase GI bleeding risk.', 'Variable change in INR with added GI ulceration risk.', 'Monitor INR when starting, changing dose of, or stopping prednisone.', 'Warfarin sodium tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0cbce382-9c88-4f58-ae0f-532a841e8f95)', true),
    ('med_clopidogrel', 'med_omeprazole', 'avoid', 'Omeprazole inhibits CYP2C19, reducing conversion of clopidogrel to its active metabolite.', 'Significantly reduced antiplatelet activity of clopidogrel, even when doses are given 12 hours apart.', 'Avoid concomitant use; if a PPI is needed, consider one with less CYP2C19 inhibition (e.g., pantoprazole).', 'PLAVIX (clopidogrel), FDA label (DailyMed), Sections 5 and 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=de8b0b67-eb25-4684-83b5-7ad785314227)', true),
    ('med_aspirin', 'med_clopidogrel', 'caution', 'Additive antiplatelet effect (P2Y12 inhibition plus COX-1 inhibition) used deliberately as dual antiplatelet therapy.', 'Recognised combination after acute coronary syndrome or stenting, but bleeding risk is increased compared with either drug alone.', 'Use for a defined indication and duration; monitor for bleeding and consider gastroprotection in high GI-risk patients.', 'PLAVIX (clopidogrel), FDA label (DailyMed), Sections 5 and 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=de8b0b67-eb25-4684-83b5-7ad785314227)', true),
    ('med_clopidogrel', 'med_ibuprofen', 'caution', 'NSAID-induced mucosal injury and platelet inhibition add to clopidogrel''s antiplatelet effect.', 'Coadministration increases the risk of gastrointestinal bleeding.', 'Avoid regular NSAID use where possible; monitor for GI bleeding.', 'PLAVIX (clopidogrel), FDA label (DailyMed), Sections 5 and 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=de8b0b67-eb25-4684-83b5-7ad785314227)', true),
    ('med_clopidogrel', 'med_nirmatrelvir_ritonavir', 'avoid', 'Ritonavir reduces formation of clopidogrel''s active metabolite.', 'Reduced antiplatelet effect, with risk of stent thrombosis or recurrent ischemic events.', 'Avoid concomitant use with nirmatrelvir/ritonavir.', 'PAXLOVID (nirmatrelvir; ritonavir), FDA label (DailyMed), Sections 4 and 7 (Table 2) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8a99d6d6-fd9e-45bb-b1bf-48c7f761232a)', true),
    ('med_clopidogrel', 'med_rifampicin', 'avoid', 'Rifampicin strongly induces CYP2C19, increasing clopidogrel active metabolite levels and platelet inhibition.', 'May potentiate the risk of bleeding.', 'As a precaution, avoid concomitant use of strong CYP2C19 inducers such as rifampicin.', 'PLAVIX (clopidogrel), FDA label (DailyMed), Sections 5 and 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=de8b0b67-eb25-4684-83b5-7ad785314227)', true),
    ('med_atorvastatin', 'med_nirmatrelvir_ritonavir', 'caution', 'Ritonavir strongly inhibits CYP3A4, increasing atorvastatin exposure.', 'Increased risk of statin-related myopathy/rhabdomyolysis.', 'Consider temporary discontinuation of atorvastatin during nirmatrelvir/ritonavir treatment.', 'PAXLOVID (nirmatrelvir; ritonavir), FDA label (DailyMed), Sections 4 and 7 (Table 2) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8a99d6d6-fd9e-45bb-b1bf-48c7f761232a)', true),
    ('med_amlodipine', 'med_nirmatrelvir_ritonavir', 'caution', 'CYP3A4 inhibition by ritonavir increases amlodipine concentrations.', 'Risk of hypotension, dizziness and peripheral edema.', 'A dose decrease may be needed; monitor blood pressure.', 'PAXLOVID (nirmatrelvir; ritonavir), FDA label (DailyMed), Sections 4 and 7 (Table 2) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8a99d6d6-fd9e-45bb-b1bf-48c7f761232a)', true),
    ('med_nirmatrelvir_ritonavir', 'med_rifampicin', 'avoid', 'Rifampicin, a strong CYP3A4 inducer, markedly lowers nirmatrelvir and ritonavir concentrations.', 'Potential loss of virologic response and possible resistance.', 'Coadministration is contraindicated.', 'PAXLOVID (nirmatrelvir; ritonavir), FDA label (DailyMed), Sections 4 and 7 (Table 2) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8a99d6d6-fd9e-45bb-b1bf-48c7f761232a)', true),
    ('med_clarithromycin', 'med_nirmatrelvir_ritonavir', 'caution', 'Ritonavir increases clarithromycin concentrations (CYP3A4 inhibition); clarithromycin also inhibits CYP3A4.', 'Increased clarithromycin exposure, including QT-related and GI adverse effects, particularly with renal impairment.', 'Refer to clarithromycin prescribing information for dose adjustment (reduction in renal impairment); consider an alternative antibiotic.', 'PAXLOVID (nirmatrelvir; ritonavir), FDA label (DailyMed), Sections 4 and 7 (Table 2) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8a99d6d6-fd9e-45bb-b1bf-48c7f761232a)', true),
    ('med_budesonide_formoterol', 'med_nirmatrelvir_ritonavir', 'caution', 'Ritonavir inhibits CYP3A4, increasing systemic exposure to budesonide.', 'Risk of Cushing''s syndrome and adrenal suppression with corticosteroids whose exposure is significantly increased by strong CYP3A inhibitors (low with a short course).', 'Monitor; alternative inhaled corticosteroids (e.g., beclomethasone) may be considered, particularly for prolonged coadministration.', 'PAXLOVID (nirmatrelvir; ritonavir), FDA label (DailyMed), Sections 4 and 7 (Table 2) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=8a99d6d6-fd9e-45bb-b1bf-48c7f761232a)', true),
    ('med_artemether_lumefantrine', 'med_rifampicin', 'avoid', 'Rifampicin, a strong CYP3A4 inducer, decreases artemether and/or lumefantrine concentrations.', 'Loss of antimalarial efficacy.', 'Coadministration is contraindicated.', 'COARTEM (artemether/lumefantrine), FDA label (DailyMed), Sections 4, 5 and 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7866ec19-dfac-47d4-a53f-511a12643cbf)', true),
    ('med_artemether_lumefantrine', 'med_azithromycin', 'caution', 'Additive QT-interval prolongation (lumefantrine and macrolide antibiotics).', 'Risk of QT prolongation and ventricular arrhythmia.', 'Use with caution; consider ECG monitoring and correct electrolytes.', 'COARTEM (artemether/lumefantrine), FDA label (DailyMed), Sections 4, 5 and 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7866ec19-dfac-47d4-a53f-511a12643cbf)', true),
    ('med_artemether_lumefantrine', 'med_ciprofloxacin', 'caution', 'Additive QT-interval prolongation (lumefantrine and fluoroquinolone antibiotics).', 'Risk of QT prolongation and ventricular arrhythmia.', 'Use with caution; consider ECG monitoring and correct electrolytes.', 'COARTEM (artemether/lumefantrine), FDA label (DailyMed), Sections 4, 5 and 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7866ec19-dfac-47d4-a53f-511a12643cbf)', true),
    ('med_artemether_lumefantrine', 'med_clarithromycin', 'avoid', 'Clarithromycin inhibits CYP3A4, increasing artemether/lumefantrine concentrations, and independently prolongs the QT interval.', 'Pharmacokinetic and pharmacodynamic potentiation of QT prolongation.', 'Avoid combination where possible; if unavoidable, use with caution and ECG monitoring.', 'COARTEM (artemether/lumefantrine), FDA label (DailyMed), Sections 4, 5 and 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7866ec19-dfac-47d4-a53f-511a12643cbf)', true),
    ('med_atorvastatin', 'med_clarithromycin', 'caution', 'Clarithromycin inhibits CYP3A4, increasing atorvastatin exposure.', 'Increased risk of myopathy/rhabdomyolysis.', 'Do not exceed atorvastatin 20 mg daily during coadministration, or withhold the statin for the antibiotic course.', 'Atorvastatin calcium tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=803b7d6f-faea-4a13-a141-f2c44d7fca72)', true),
    ('med_amlodipine', 'med_clarithromycin', 'caution', 'Clarithromycin inhibits CYP3A4 metabolism of amlodipine.', 'Hypotension and acute kidney injury have been reported with CYP3A4-metabolised calcium channel blockers.', 'Monitor for hypotension and renal function; consider azithromycin as an alternative macrolide.', 'Clarithromycin tablets, FDA label (DailyMed), Warnings and Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b98b02bb-2609-49a0-b29f-e5911aa0cbc1)', true),
    ('med_atorvastatin', 'med_rifampicin', 'caution', 'Rifampicin induces CYP3A4 and inhibits the hepatic uptake transporter OATP1B1 (dual mechanism).', 'Delayed administration of atorvastatin after rifampicin is associated with a significant reduction in atorvastatin concentrations.', 'Administer atorvastatin and rifampicin simultaneously; monitor lipid response.', 'Atorvastatin calcium tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=803b7d6f-faea-4a13-a141-f2c44d7fca72)', true),
    ('med_enalapril', 'med_losartan', 'avoid', 'Dual blockade of the renin-angiotensin system (ARB plus ACE inhibitor).', 'Increased risks of hypotension, syncope, hyperkalemia and changes in renal function, including acute renal failure, without added benefit in most patients.', 'Avoid combined use of an ARB and an ACE inhibitor.', 'Losartan potassium tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1dadbe02-289c-4312-9e65-40f3314dcc31)', true),
    ('med_losartan', 'med_spironolactone', 'caution', 'Both drugs raise serum potassium (reduced aldosterone effect).', 'Risk of severe hyperkalemia, increased with impaired renal function.', 'Monitor serum potassium within 1 week of initiation or titration and regularly thereafter; used together in heart failure with monitoring.', 'ALDACTONE (spironolactone), FDA label, Sections 5.1 and 7.1 (https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/012151s080lbl.pdf)', true),
    ('med_azithromycin', 'med_warfarin', 'caution', 'Postmarketing reports suggest azithromycin may potentiate the effect of warfarin; infection and reduced vitamin K intake can also raise INR.', 'Possible INR elevation and bleeding during the antibiotic course.', 'Carefully monitor prothrombin time/INR during coadministration.', 'ZITHROMAX (azithromycin), FDA label (DailyMed), Sections 5.4 and 7.2 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=db52b91e-79f7-4cc1-9564-f2eee8e31c45)', true),
    ('med_amoxicillin', 'med_warfarin', 'caution', 'Antibiotics may raise INR (altered gut flora vitamin K production, acute illness); INR changes are reported when antibiotic courses are started or stopped.', 'Possible INR elevation and bleeding.', 'Closely monitor INR when starting or stopping any antibiotic.', 'Warfarin sodium tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0cbce382-9c88-4f58-ae0f-532a841e8f95)', true),
    ('med_coamoxiclav', 'med_warfarin', 'caution', 'Antibiotics may raise INR (altered gut flora vitamin K production, acute illness); INR changes are reported when antibiotic courses are started or stopped.', 'Possible INR elevation and bleeding.', 'Closely monitor INR when starting or stopping any antibiotic.', 'Warfarin sodium tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0cbce382-9c88-4f58-ae0f-532a841e8f95)', true),
    ('med_doxycycline', 'med_warfarin', 'caution', 'Antibiotics, including tetracyclines, may enhance warfarin effect (altered vitamin K-producing gut flora, acute illness); INR changes are reported when antibiotic courses are started or stopped.', 'Possible INR elevation and bleeding.', 'Closely monitor INR when starting or stopping any antibiotic; warfarin dose reduction may be needed.', 'Warfarin sodium tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0cbce382-9c88-4f58-ae0f-532a841e8f95)', true),
    ('med_paracetamol', 'med_warfarin', 'caution', 'Regular paracetamol use (rather than occasional doses) has been associated with a rise in INR; mechanism not fully established.', 'Sustained daily paracetamol may increase INR and bleeding risk, although it remains the preferred analgesic over NSAIDs in anticoagulated patients.', 'Occasional use acceptable; monitor INR if paracetamol is taken regularly for several days or the dose is changed.', 'Acetaminophen 500 mg tablets, OTC Drug Facts label (DailyMed), Warnings (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2651bf11-4d66-43ba-e054-00144ff88e88)', true),
    ('med_aspirin', 'med_ibuprofen', 'caution', 'Ibuprofen competitively blocks access of low-dose aspirin to platelet COX-1, which can reduce aspirin''s irreversible antiplatelet effect; both also injure the GI mucosa.', 'Possible loss of cardioprotective benefit of aspirin and increased GI bleeding risk.', 'Concomitant use not generally recommended; if occasional ibuprofen is needed, separate dosing from immediate-release aspirin and prefer paracetamol for regular analgesia.', 'Advil Dual Action with Acetaminophen (ibuprofen/acetaminophen), OTC Drug Facts label (DailyMed) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f5ea858e-76d9-4777-b3dc-5d614f66d485)', true),
    ('med_ibuprofen', 'med_mefenamic_acid', 'avoid', 'Duplicate NSAID therapy with additive COX inhibition.', 'Increased GI ulceration/bleeding and renal toxicity without added analgesic benefit.', 'Concomitant use of two NSAIDs is not recommended; use one NSAID at a time.', 'Mefenamic acid capsules, FDA label (DailyMed), Section 7.1 (Table 1) (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=4b0788cd-bdca-4fa5-9eba-01a270613aab)', true),
    ('med_ibuprofen', 'med_prednisone', 'caution', 'Additive injury to the gastric mucosa (corticosteroid impairs mucosal healing; NSAID inhibits protective prostaglandins).', 'Concomitant oral corticosteroid use is a recognised risk factor for NSAID-associated GI bleeding.', 'Use lowest effective NSAID dose for shortest time; consider gastroprotection (e.g., a PPI) and monitor for GI bleeding.', 'Prednisone tablets, FDA label (DailyMed), Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=10fe5a3b-84dc-4600-87c2-b80c97ce18cf)', true),
    ('med_mefenamic_acid', 'med_prednisone', 'caution', 'Additive injury to the gastric mucosa (corticosteroid plus NSAID).', 'Increased risk of GI ulceration and bleeding.', 'Use lowest effective NSAID dose for shortest time; consider gastroprotection and monitor for GI bleeding.', 'Prednisone tablets, FDA label (DailyMed), Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=10fe5a3b-84dc-4600-87c2-b80c97ce18cf)', true),
    ('med_aspirin', 'med_prednisone', 'caution', 'Additive GI mucosal injury; corticosteroids increase salicylate clearance.', 'Increased GI adverse effects; salicylate levels may fall during steroid therapy and rise (toxicity risk) on steroid withdrawal (mainly relevant to higher aspirin doses).', 'Monitor for GI bleeding; consider gastroprotection in high-risk patients.', 'Prednisone tablets, FDA label (DailyMed), Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=10fe5a3b-84dc-4600-87c2-b80c97ce18cf)', true),
    ('med_enalapril', 'med_spironolactone', 'caution', 'ACE inhibition lowers aldosterone while spironolactone blocks mineralocorticoid receptors; both retain potassium.', 'Significant increases in serum potassium, especially with renal impairment.', 'Monitor serum potassium and renal function within 1 week of initiation or titration and regularly thereafter; used together in heart failure with monitoring.', 'Enalapril maleate tablets, FDA label (DailyMed), Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1044ee11-1d9c-5435-e054-00144ff88e88)', true),
    ('med_ibuprofen', 'med_losartan', 'caution', 'NSAIDs inhibit renal prostaglandins, opposing ARB effects on blood pressure and reducing glomerular perfusion.', 'Attenuated antihypertensive effect; deterioration of renal function, including acute renal failure, in elderly, volume-depleted or renally impaired patients.', 'Avoid regular NSAID use where possible; if used, monitor blood pressure and renal function.', 'Losartan potassium tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1dadbe02-289c-4312-9e65-40f3314dcc31)', true),
    ('med_enalapril', 'med_ibuprofen', 'caution', 'NSAIDs inhibit renal prostaglandins, opposing ACE inhibitor effects on blood pressure and glomerular perfusion.', 'Diminished antihypertensive effect; deterioration of renal function, including possible acute renal failure, particularly in elderly or volume-depleted patients.', 'Avoid regular NSAID use where possible; if used, monitor blood pressure and renal function.', 'Enalapril maleate tablets, FDA label (DailyMed), Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1044ee11-1d9c-5435-e054-00144ff88e88)', true),
    ('med_furosemide', 'med_ibuprofen', 'caution', 'NSAIDs inhibit renal prostaglandin synthesis, reducing the natriuretic and antihypertensive effects of loop diuretics.', 'Reduced diuretic response (relevant in heart failure) and risk of renal failure.', 'Observe closely for reduced diuretic effect and signs of renal failure.', 'Ibuprofen tablets, FDA label (DailyMed), Drug Interactions / Warnings (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=888a5dbc-9464-e272-e053-2a95a90ad687)', true),
    ('med_hydrochlorothiazide', 'med_ibuprofen', 'caution', 'NSAIDs reduce the diuretic, natriuretic and antihypertensive effects of thiazides via prostaglandin inhibition.', 'Reduced blood pressure control and risk of renal impairment.', 'Monitor blood pressure and renal function; prefer paracetamol for regular analgesia.', 'HYZAAR (losartan/hydrochlorothiazide), FDA label (DailyMed), Indications and Section 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4116ccde-2e23-45f4-b12f-6337df877744)', true),
    ('med_ibuprofen', 'med_spironolactone', 'caution', 'NSAIDs reduce renal potassium excretion and renal perfusion; spironolactone retains potassium.', 'Severe hyperkalemia and reduced renal function may occur.', 'Avoid regular NSAID use where possible; monitor serum potassium and renal function.', 'ALDACTONE (spironolactone), FDA label, Sections 5.1 and 7.1 (https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/012151s080lbl.pdf)', true),
    ('med_enalapril', 'med_furosemide', 'caution', 'Diuretic-induced volume and sodium depletion activates the renin-angiotensin system, so ACE inhibitor initiation causes a larger fall in blood pressure.', 'Excessive first-dose hypotension; combination may also cause deterioration of renal function.', 'Start enalapril at a low dose (consider reducing or pausing the diuretic beforehand) and monitor blood pressure and renal function.', 'Enalapril maleate tablets, FDA label (DailyMed), Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1044ee11-1d9c-5435-e054-00144ff88e88)', true),
    ('med_furosemide', 'med_prednisone', 'caution', 'Both drugs increase urinary potassium loss.', 'Additive hypokalemia, with risk of arrhythmia.', 'Monitor serum potassium; potassium supplementation may be needed.', 'LASIX (furosemide), FDA label (DailyMed), Precautions / Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=2c9b4d8f-0770-482d-a9e6-9c616a440b1a)', true),
    ('med_hydrochlorothiazide', 'med_prednisone', 'caution', 'Corticosteroids intensify thiazide-induced electrolyte depletion.', 'Additive hypokalemia; corticosteroids may also raise blood glucose.', 'Monitor serum potassium.', 'Prednisone tablets, FDA label (DailyMed), Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=10fe5a3b-84dc-4600-87c2-b80c97ce18cf)', true),
    ('med_furosemide', 'med_salbutamol', 'caution', 'Beta-2 agonists shift potassium into cells; loop diuretics increase potassium loss.', 'ECG changes and/or hypokalemia from non-potassium-sparing diuretics can be acutely worsened, especially when beta-agonist doses are exceeded.', 'Use with caution; monitor serum potassium, particularly with high or frequent salbutamol doses.', 'Albuterol sulfate HFA inhalation aerosol, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7bb5b6dd-9105-4ee7-b205-ed79cf4b371b)', true),
    ('med_metoprolol', 'med_salbutamol', 'caution', 'Beta-blockers antagonise the bronchodilator effect of beta-2 agonists; metoprolol is beta-1 selective, but selectivity is dose-dependent.', 'Reduced salbutamol response and possible bronchospasm in patients with asthma.', 'Beta-blockers are generally avoided in asthma; a cardioselective agent such as metoprolol may be used with caution when there is a compelling indication.', 'Albuterol sulfate HFA inhalation aerosol, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=7bb5b6dd-9105-4ee7-b205-ed79cf4b371b)', true),
    ('med_budesonide_formoterol', 'med_metoprolol', 'caution', 'Beta-blockers antagonise the bronchodilator effect of formoterol.', 'Reduced bronchodilator response and possible severe bronchospasm in patients with asthma.', 'Patients with asthma should not normally be treated with beta-blockers; if required, use a cardioselective agent with caution.', 'SYMBICORT (budesonide/formoterol), FDA label (DailyMed), Sections 5.9 and 7 (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=a645756c-c692-4bc6-a858-7e7e249561bd&type=display)', true),
    ('med_budesonide_formoterol', 'med_clarithromycin', 'caution', 'Clarithromycin, a strong CYP3A4 inhibitor, may inhibit budesonide metabolism and increase its systemic exposure.', 'Increased systemic corticosteroid effects (e.g., adrenal suppression), mainly with prolonged coadministration.', 'Exercise caution; usually acceptable for a short antibiotic course.', 'SYMBICORT (budesonide/formoterol), FDA label (DailyMed), Sections 5.9 and 7 (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=a645756c-c692-4bc6-a858-7e7e249561bd&type=display)', true),
    ('med_gliclazide', 'med_rifampicin', 'caution', 'Rifampicin induces CYP2C9 and other enzymes that metabolise sulfonylureas (label names glyburide and glipizide; gliclazide is a CYP2C9 substrate).', 'Reduced sulfonylurea exposure; rifampicin may worsen glucose control.', 'Monitor blood glucose during and after rifampicin therapy; adjust sulfonylurea dose.', 'RIFADIN (rifampin), FDA label (DailyMed), Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=036ab68e-5085-4edc-bd83-784b43d64eab&type=display)', true),
    ('med_amlodipine', 'med_rifampicin', 'caution', 'Rifampicin strongly induces CYP3A4; the label lists decreased exposure of CYP3A4-metabolised calcium channel blockers (e.g., nifedipine), and amlodipine is a CYP3A4 substrate.', 'Reduced antihypertensive effect.', 'Monitor blood pressure; dose adjustment or an alternative agent may be needed.', 'RIFADIN (rifampin), FDA label (DailyMed), Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=036ab68e-5085-4edc-bd83-784b43d64eab&type=display)', true),
    ('med_prednisone', 'med_rifampicin', 'caution', 'Rifampicin induces CYP3A4, enhancing metabolism of prednisolone (the active metabolite of prednisone).', 'Reduced corticosteroid effect.', 'Corticosteroid dose increase may be needed during rifampicin therapy; monitor clinical response.', 'Prednisone tablets, FDA label (DailyMed), Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=10fe5a3b-84dc-4600-87c2-b80c97ce18cf)', true),
    ('med_clarithromycin', 'med_rifampicin', 'caution', 'Rifampicin induces CYP3A4, decreasing clarithromycin exposure.', 'Reduced clarithromycin concentrations and possible loss of antibacterial efficacy.', 'Avoid if possible or monitor clinical response; consider an alternative antibiotic.', 'RIFADIN (rifampin), FDA label (DailyMed), Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=036ab68e-5085-4edc-bd83-784b43d64eab&type=display)', true),
    ('med_isoniazid', 'med_rifampicin', 'caution', 'Both drugs are hepatotoxic; given together, the potential for hepatotoxicity is increased. The combination is used together by design in standard tuberculosis regimens.', 'Recognised first-line tuberculosis combination, with increased risk of drug-induced liver injury.', 'Monitor for symptoms of hepatitis and check liver function tests (baseline and periodically in at-risk patients).', 'RIFADIN (rifampin), FDA label (DailyMed), Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=036ab68e-5085-4edc-bd83-784b43d64eab&type=display)', true),
    ('med_isoniazid', 'med_paracetamol', 'caution', 'Isoniazid induces CYP2E1, which may increase conversion of paracetamol to its hepatotoxic metabolite (NAPQI).', 'Severe paracetamol toxicity has been reported in a patient receiving isoniazid; additive hepatotoxicity.', 'Keep paracetamol within recommended dose limits and avoid prolonged high-dose use; monitor liver function.', 'Isoniazid tablets, FDA label (DailyMed), Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1169212a-8192-5337-e054-00144ff88e88)', true),
    ('med_azithromycin', 'med_ciprofloxacin', 'caution', 'Additive QT-interval prolongation (macrolide plus fluoroquinolone).', 'Increased risk of QT prolongation and torsades de pointes, particularly in elderly patients or with electrolyte disturbance.', 'Avoid combination where possible; if necessary, correct electrolytes and consider ECG monitoring.', 'Ciprofloxacin tablets, FDA label (DailyMed), Boxed Warning, Section 5 and Section 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5f4e80a1-0225-63dd-e053-2991aa0aa7fb)', true),
    ('med_ciprofloxacin', 'med_prednisone', 'caution', 'Fluoroquinolone tendinopathy risk is increased by concomitant corticosteroids.', 'Increased risk of tendinitis and tendon rupture (boxed warning), especially in patients over 60 years.', 'Avoid combination where possible; discontinue ciprofloxacin at first sign of tendon pain or inflammation.', 'Ciprofloxacin tablets, FDA label (DailyMed), Boxed Warning, Section 5 and Section 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5f4e80a1-0225-63dd-e053-2991aa0aa7fb)', true),
    ('med_ciprofloxacin', 'med_gliclazide', 'caution', 'Fluoroquinolones cause dysglycemia; hypoglycemia has been reported with sulfonylureas.', 'Hypoglycemia, sometimes severe.', 'Monitor blood glucose closely during coadministration.', 'Ciprofloxacin tablets, FDA label (DailyMed), Boxed Warning, Section 5 and Section 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5f4e80a1-0225-63dd-e053-2991aa0aa7fb)', true),
    ('med_clarithromycin', 'med_gliclazide', 'caution', 'Clarithromycin coadministered with oral hypoglycemic agents can cause significant hypoglycemia.', 'Risk of significant hypoglycemia.', 'Monitor blood glucose carefully during the antibiotic course.', 'Clarithromycin tablets, FDA label (DailyMed), Warnings and Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=b98b02bb-2609-49a0-b29f-e5911aa0cbc1)', true),
    ('med_metformin', 'med_prednisone', 'caution', 'Corticosteroids raise blood glucose (increased gluconeogenesis, insulin resistance).', 'Loss of glycemic control.', 'Monitor blood glucose; antidiabetic dose adjustment may be required during and after corticosteroid therapy.', 'Metformin hydrochloride tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4d3dbf6f-1c8a-4daa-8343-8cd8f64a65cd)', true),
    ('med_gliclazide', 'med_prednisone', 'caution', 'Corticosteroids raise blood glucose, opposing sulfonylurea effect.', 'Loss of glycemic control during steroid therapy; hypoglycemia risk when steroid is tapered if sulfonylurea dose was increased.', 'Monitor blood glucose; adjust sulfonylurea dose during and after corticosteroid therapy.', 'Prednisone tablets, FDA label (DailyMed), Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=10fe5a3b-84dc-4600-87c2-b80c97ce18cf)', true),
    ('med_dapagliflozin', 'med_furosemide', 'caution', 'Additive osmotic diuresis and natriuresis.', 'Increased risk of volume depletion and hypotension, especially in elderly patients or those with eGFR below 60.', 'Assess volume status before starting; consider reducing the loop diuretic dose and monitor for hypotension and renal function.', 'FARXIGA (dapagliflozin), FDA label (DailyMed), Sections 5.2 and 5.4 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=72ad22ae-efe6-4cd6-a302-98aaee423d69)', true),
    ('med_hydrochlorothiazide', 'med_losartan', 'safe', 'Complementary antihypertensive mechanisms; available as a fixed-dose combination. Losartan also attenuates thiazide-induced hyperuricemia.', 'Recognised combination for hypertension.', 'Compatible combination; monitor blood pressure, electrolytes and renal function as usual.', 'HYZAAR (losartan/hydrochlorothiazide), FDA label (DailyMed), Indications and Section 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4116ccde-2e23-45f4-b12f-6337df877744)', true),
    ('med_amlodipine', 'med_losartan', 'safe', 'Complementary antihypertensive mechanisms (calcium channel blockade plus angiotensin receptor blockade); no significant pharmacokinetic interaction.', 'Recommended dual combination for hypertension (CCB plus ARB).', 'Compatible combination; monitor blood pressure.', '2020 International Society of Hypertension Global Hypertension Practice Guidelines (Hypertension 2020;75:1334-57), Drug treatment (https://www.ahajournals.org/doi/10.1161/HYPERTENSIONAHA.120.15026)', true),
    ('med_gliclazide', 'med_metformin', 'safe', 'Complementary glucose-lowering mechanisms (reduced hepatic glucose output plus insulin secretion).', 'Recognised combination for type 2 diabetes; adding a sulfonylurea increases hypoglycemia risk.', 'Compatible combination; monitor for hypoglycemia and consider lower sulfonylurea dose.', 'Metformin hydrochloride tablets, FDA label (DailyMed), Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=4d3dbf6f-1c8a-4daa-8343-8cd8f64a65cd)', true),
    ('med_ibuprofen', 'med_paracetamol', 'safe', 'Different analgesic mechanisms; available together as a fixed-dose OTC combination.', 'Recognised combination for short-term pain relief.', 'Compatible combination; keep total daily paracetamol and ibuprofen within recommended limits and avoid other paracetamol-containing products.', 'Advil Dual Action with Acetaminophen (ibuprofen/acetaminophen), OTC Drug Facts label (DailyMed) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f5ea858e-76d9-4777-b3dc-5d614f66d485)', true),
    ('med_dapagliflozin', 'med_metformin', 'safe', 'Complementary glucose-lowering mechanisms; available as a fixed-dose combination.', 'Recognised combination for type 2 diabetes.', 'Compatible combination; monitor renal function and volume status.', 'XIGDUO XR (dapagliflozin/metformin ER), FDA label (DailyMed), Indications (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=ac8a0f7b-9f69-4495-abbc-3a47cd75a859)', true),
    ('med_amlodipine', 'med_metoprolol', 'safe', 'Dihydropyridine calcium channel blocker plus beta-blocker; amlodipine does not add to the AV-nodal effects of beta-blockade (unlike verapamil or diltiazem).', 'Recognised combination in hypertension and angina; additive blood-pressure lowering.', 'Compatible combination; monitor blood pressure and heart rate.', 'Standard co-prescription in hypertension and angina practice (dihydropyridine CCB with a beta-blocker)', true),
    ('med_ibuprofen', 'med_tenofovir', 'caution', 'Tenofovir is eliminated by glomerular filtration and active tubular secretion and is itself associated with renal tubular injury; NSAIDs reduce renal prostaglandin-mediated perfusion and are nephrotoxic at high or repeated doses.', 'Acute renal failure has been reported after initiation of high-dose or multiple NSAIDs in HIV-infected patients with risk factors for renal dysfunction who appeared stable on tenofovir disoproxil fumarate.', 'Tenofovir DF is avoided with concurrent or recent high-dose or multiple NSAID use; alternatives to NSAIDs (e.g., paracetamol) are considered in patients at risk for renal dysfunction. If coadministered, serum creatinine, creatinine clearance, urine glucose and urine protein are monitored.', 'VIREAD (tenofovir disoproxil fumarate) FDA label (DailyMed), Sections 5.2 and 7.1 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=33fd6418-fbdc-42ca-a50d-ce2a476a5418)', true),
    ('med_mefenamic_acid', 'med_tenofovir', 'caution', 'Mefenamic acid is an NSAID; NSAID-induced reduction in renal perfusion adds to the tubular nephrotoxicity risk of tenofovir, which is renally eliminated.', 'The tenofovir DF label warns of acute renal failure after initiation of high-dose or multiple NSAIDs in patients with renal risk factors, and lists NSAIDs among drugs that may increase tenofovir concentrations.', 'Avoid concurrent or recent high-dose or multiple NSAID use with tenofovir DF; prefer a non-NSAID analgesic in patients at renal risk, and monitor renal function if the combination is used.', 'VIREAD (tenofovir disoproxil fumarate) FDA label (DailyMed), Sections 5.2 and 7.1 (NSAID class statement) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=33fd6418-fbdc-42ca-a50d-ce2a476a5418)', true),
    ('med_aciclovir', 'med_tenofovir', 'caution', 'Tenofovir and aciclovir are both eliminated by the kidney partly via active tubular secretion; coadministration may increase serum concentrations of either drug.', 'Higher tenofovir exposure increases the risk of renal adverse reactions (acute kidney injury, proximal tubulopathy/Fanconi syndrome).', 'Monitor renal function (serum creatinine, creatinine clearance, urine glucose/protein, phosphorus in CKD) during coadministration, particularly with high-dose intravenous aciclovir or pre-existing renal impairment.', 'VIREAD (tenofovir disoproxil fumarate) FDA label (DailyMed), Section 7.1 Drugs Affecting Renal Function (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=33fd6418-fbdc-42ca-a50d-ce2a476a5418)', true),
    ('med_ibuprofen', 'med_tld', 'caution', 'The tenofovir disoproxil fumarate component of TLD is renally eliminated and nephrotoxic; NSAIDs impair renal perfusion.', 'Labels for lamivudine/tenofovir DF combinations state that coadministration should be avoided with concurrent or recent use of a nephrotoxic agent such as high-dose or multiple NSAIDs, because of the risk of acute renal failure.', 'Prefer paracetamol for analgesia in people on TLD, especially with renal risk factors; if an NSAID is needed, use briefly at the lowest dose with monitoring of renal function.', 'CIMDUO (lamivudine and tenofovir disoproxil fumarate) FDA label (DailyMed), Warnings (new onset or worsening renal impairment) and Drug Interactions; applies to the TDF/3TC component of TLD (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a300f04d-118f-4136-aaf3-ddfd00197f86)', true),
    ('med_mefenamic_acid', 'med_tld', 'caution', 'Mefenamic acid is an NSAID; NSAID-related renal hypoperfusion adds to the tubular nephrotoxicity risk of the tenofovir DF component of TLD.', 'Labels for lamivudine/tenofovir DF combinations advise avoiding concurrent or recent use of nephrotoxic agents such as high-dose or multiple NSAIDs.', 'Prefer a non-NSAID analgesic; if used (e.g., short courses for dysmenorrhea), keep to the lowest dose and shortest duration and monitor renal function in those with renal risk factors.', 'CIMDUO (lamivudine and tenofovir disoproxil fumarate) FDA label (DailyMed), Warnings and Drug Interactions (NSAID class statement); applies to the TDF/3TC component of TLD (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a300f04d-118f-4136-aaf3-ddfd00197f86)', true),
    ('med_aciclovir', 'med_tld', 'caution', 'Aciclovir competes with tenofovir for active renal tubular secretion; coadministration may increase serum concentrations of tenofovir and/or aciclovir.', 'Raised tenofovir exposure increases the risk of renal toxicity; the combination is common in people with HIV treated for herpes simplex or varicella-zoster infection.', 'Monitor renal function during coadministration, especially with intravenous or high-dose aciclovir, dehydration or pre-existing renal impairment; adjust aciclovir dose to creatinine clearance.', 'CIMDUO (lamivudine and tenofovir disoproxil fumarate) FDA label (DailyMed), Drug Interactions: drugs affecting renal function (acyclovir, valacyclovir) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=a300f04d-118f-4136-aaf3-ddfd00197f86)', true),
    ('med_metformin', 'med_tld', 'caution', 'Dolutegravir inhibits the renal transporters OCT2 and MATE1, reducing tubular secretion of metformin. Dolutegravir 50 mg once daily increased metformin AUC by 79% and Cmax by 66%; twice-daily dolutegravir increased AUC by 145%.', 'Increased metformin exposure raises the risk of gastrointestinal adverse effects and, particularly with renal impairment, lactic acidosis; stopping dolutegravir can reduce glycaemic control.', 'Consider metformin dose adjustment when starting or stopping dolutegravir; the US prescribing information suggests limiting total daily metformin to 1,000 mg when starting either drug. Monitor renal function and blood glucose when starting and stopping coadministration.', 'Liverpool HIV Drug Interactions: Dolutegravir + Metformin (Potential Interaction); TIVICAY FDA label Table of drug interactions (https://www.hiv-druginteractions.org/interactions/81694)', true),
    ('med_rifampicin', 'med_tld', 'caution', 'Rifampicin strongly induces UGT1A1 and CYP3A, which metabolize dolutegravir, markedly lowering dolutegravir concentrations.', 'Once-daily dolutegravir exposure with rifampicin is insufficient and risks virologic failure and integrase resistance, a common issue in HIV/TB co-infection.', 'The dolutegravir dose is increased to 50 mg twice daily during rifampicin coadministration in integrase-inhibitor-naive adults (for a TLD regimen, by adding a separate dolutegravir 50 mg dose); this adjustment is not suitable for integrase-experienced patients with suspected INSTI resistance.', 'TIVICAY (dolutegravir) FDA label (DailyMed), Section 2 Dosage and Section 7 Table of established drug interactions (rifampin) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=63df5af3-b8ac-4e76-9830-2dbb340af922)', true),
    ('med_tld', 'med_zinc_sulfate', 'caution', 'Zinc and other polyvalent cations chelate dolutegravir in the gastrointestinal tract, reducing its absorption.', 'Reduced dolutegravir concentrations may compromise viral suppression; evidence quality for zinc specifically is very low but the effect is expected by class.', 'Administer dolutegravir-containing regimens 2 hours before or 6 hours after zinc-containing products, or take them together with food.', 'Liverpool HIV Drug Interactions: Dolutegravir/lamivudine + Zinc (Potential Interaction); TIVICAY FDA label (polyvalent cations) (https://www.hiv-druginteractions.org/interactions/143345)', true),
    ('med_omeprazole', 'med_tld', 'safe', 'Dolutegravir absorption is not meaningfully affected by gastric acid suppression; omeprazole is not listed among drugs requiring dose change with dolutegravir.', 'The dolutegravir label lists omeprazole among drugs without clinically significant interactions.', 'Can be coadministered without dose adjustment (note: this does not apply to cation-containing antacids, which require dose separation).', 'TIVICAY (dolutegravir) FDA label (DailyMed), Section 7 Drugs without Clinically Significant Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=63df5af3-b8ac-4e76-9830-2dbb340af922)', true),
    ('med_prednisone', 'med_tld', 'safe', 'Prednisone did not meaningfully alter dolutegravir pharmacokinetics in interaction studies.', 'The dolutegravir label lists prednisone among drugs that can be coadministered without dose adjustment.', 'Can be coadministered without dose adjustment of the dolutegravir component.', 'TIVICAY (dolutegravir) FDA label (DailyMed), Section 7 Drugs without Clinically Significant Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=63df5af3-b8ac-4e76-9830-2dbb340af922)', true),
    ('med_cotrimoxazole', 'med_tld', 'safe', 'Trimethoprim inhibits renal cationic secretion of lamivudine; co-trimoxazole increased lamivudine AUC by about 43% and reduced its renal clearance by about 30%.', 'The increase is not considered clinically significant at standard co-trimoxazole doses; the combination is routine when co-trimoxazole prophylaxis is given with antiretroviral therapy. Effects of high (PCP-treatment) doses on lamivudine have not been studied.', 'No dose adjustment of lamivudine is needed at standard co-trimoxazole doses; renal function is reviewed in patients with renal impairment.', 'EPIVIR (lamivudine) FDA label (DailyMed), Section 7 Drug Interactions (trimethoprim/sulfamethoxazole); applies to the lamivudine component of TLD (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=89226149-47fa-4f7d-bb1f-1aa7034486b8)', true),
    ('med_entecavir', 'med_tenofovir', 'safe', 'Both are renally eliminated HBV antivirals, but interaction studies showed no change in the steady-state pharmacokinetics of either drug.', 'Entecavir is not a CYP450 substrate, inhibitor or inducer; no pharmacokinetic interaction was observed with tenofovir DF, lamivudine or adefovir.', 'No pharmacokinetic dose adjustment is required; both drugs are dose-adjusted for creatinine clearance below 50 mL/min and renal function is monitored.', 'BARACLUDE (entecavir) FDA label (DailyMed), Section 7 Drug Interactions and Clinical Pharmacology (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=046e61c9-9298-4b2e-b76e-b26b81fecd20)', true),
    ('med_cotrimoxazole', 'med_warfarin', 'caution', 'Sulfamethoxazole inhibits CYP2C9, the main enzyme metabolizing S-warfarin, and may displace warfarin from protein binding.', 'Co-trimoxazole may prolong prothrombin time and raise INR, increasing bleeding risk.', 'Monitor INR closely during and shortly after co-trimoxazole therapy and adjust warfarin dose as needed; an alternative antibiotic may be considered.', 'BACTRIM (sulfamethoxazole and trimethoprim) FDA label (DailyMed), Precautions - Drug Interactions (warfarin) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f59d0c04-9c66-4d53-a0e1-cb55570deb62)', true),
    ('med_cotrimoxazole', 'med_metformin', 'caution', 'Trimethoprim inhibits the renal organic cation transporter OCT2 (and MATE), reducing tubular secretion of metformin.', 'Co-trimoxazole potentiates the glucose-lowering effect of metformin; increased metformin exposure is a concern in renal impairment.', 'Monitor blood glucose during coadministration and review renal function; adjust antidiabetic therapy as needed.', 'BACTRIM (sulfamethoxazole and trimethoprim) FDA label (DailyMed), Precautions - Drug Interactions (oral hypoglycemics eliminated renally via OCT2) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f59d0c04-9c66-4d53-a0e1-cb55570deb62)', true),
    ('med_cotrimoxazole', 'med_gliclazide', 'caution', 'Sulfonamides potentiate the glucose-lowering effect of sulfonylureas; sulfamethoxazole inhibits CYP2C9, a pathway of sulfonylurea metabolism.', 'Potentiation of the blood-glucose-lowering effect, and in some instances hypoglycaemia, may occur, particularly in older adults or with renal impairment.', 'Monitor blood glucose closely during and after the co-trimoxazole course and adjust the gliclazide dose as needed.', 'Gliclazide MR Canadian product monograph (Drug Interactions: sulfonamides); BACTRIM FDA label (CYP2C9 sulfonylurea potentiation) (https://pdf.hres.ca/dpd_pm/00075650.PDF)', true),
    ('med_cotrimoxazole', 'med_enalapril', 'caution', 'Trimethoprim blocks the epithelial sodium channel in the distal nephron (amiloride-like effect), reducing potassium excretion; ACE inhibitors reduce aldosterone.', 'Additive potassium retention; hyperkalemia has been reported in elderly patients after concomitant co-trimoxazole and an ACE inhibitor.', 'Monitor serum potassium closely, especially in older adults and renal impairment; consider an alternative antibiotic when clinically appropriate.', 'BACTRIM (sulfamethoxazole and trimethoprim) FDA label (DailyMed), Precautions - Drug Interactions (angiotensin converting enzyme inhibitor) and Hyperkalemia (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f59d0c04-9c66-4d53-a0e1-cb55570deb62)', true),
    ('med_cotrimoxazole', 'med_losartan', 'caution', 'Trimethoprim''s amiloride-like reduction of distal potassium secretion adds to the aldosterone-lowering effect of angiotensin receptor blockers.', 'In a population-based study of older adults on ACE inhibitors or ARBs, co-trimoxazole was associated with about a 7-fold higher risk of hospital admission for hyperkalemia compared with amoxicillin (adjusted OR 6.7).', 'Consider an alternative antibiotic when clinically appropriate; if co-trimoxazole is used, monitor serum potassium and renal function.', 'Antoniou T et al. Trimethoprim-Sulfamethoxazole-Induced Hyperkalemia in Patients Receiving Inhibitors of the Renin-Angiotensin System. Arch Intern Med. 2010 (https://jamanetwork.com/journals/jamainternalmedicine/fullarticle/416098)', true),
    ('med_cotrimoxazole', 'med_spironolactone', 'caution', 'Trimethoprim and spironolactone both reduce renal potassium excretion (ENaC blockade and mineralocorticoid receptor antagonism).', 'Concomitant use may result in clinically relevant hyperkalaemia; EU product information for spironolactone was updated to include this interaction. Observational data in older adults show a markedly increased risk of hyperkalaemia admission.', 'Prefer an alternative antibiotic where feasible; if used together, monitor serum potassium and renal function closely and consider temporary dose reduction of spironolactone.', 'EMA CMDh scientific conclusions, altizide/spironolactone PSUSA (2015): interaction with trimethoprim/sulfamethoxazole (https://www.ema.europa.eu/en/documents/psusa/altizide/spironolactone-cmdh-scientific-conclusions-grounds-variation-amendments-product-information/000002781/201501_en.pdf)', true),
    ('med_cotrimoxazole', 'med_hydrochlorothiazide', 'caution', 'Mechanism is not established; the interaction is reported with concurrent sulfonamide-trimethoprim and diuretic therapy, primarily thiazides.', 'An increased incidence of thrombocytopenia with purpura has been reported in elderly patients receiving certain diuretics, primarily thiazides, with co-trimoxazole.', 'In older adults, monitor for bruising, petechiae or bleeding and check platelet count if symptoms occur.', 'BACTRIM (sulfamethoxazole and trimethoprim) FDA label (DailyMed), Precautions - Drug Interactions (diuretics) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f59d0c04-9c66-4d53-a0e1-cb55570deb62)', true),
    ('med_praziquantel', 'med_rifampicin', 'avoid', 'Rifampicin is a strong CYP3A inducer and markedly reduces praziquantel plasma concentrations.', 'Concomitant use can lead to subtherapeutic praziquantel levels and treatment failure; the label lists it as a contraindication.', 'Contraindicated. If praziquantel treatment is required, the label advises discontinuing rifampicin 2-4 weeks beforehand; rifampicin can be restarted one day after praziquantel treatment is completed.', 'BILTRICIDE (praziquantel) FDA label (DailyMed), Section 4 Contraindications and Section 7 Drug Interactions (strong CYP3A inducers) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=34ce1cdd-648e-4f1e-8512-bf3d4cc22eb9)', true),
    ('med_nirmatrelvir_ritonavir', 'med_praziquantel', 'caution', 'Ritonavir inhibits CYP3A-mediated metabolism of praziquantel.', 'Praziquantel plasma concentrations may increase, which may increase dose-related adverse effects (dizziness, headache, abdominal discomfort).', 'Monitor for praziquantel adverse effects; where feasible, deworming can be timed after the 5-day nirmatrelvir/ritonavir course.', 'BILTRICIDE (praziquantel) FDA label (DailyMed), Section 7 Drug Interactions (CYP450 inhibitors including ritonavir) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=34ce1cdd-648e-4f1e-8512-bf3d4cc22eb9)', true),
    ('med_prednisone', 'med_rabies_vaccine', 'caution', 'Systemic corticosteroids and other immunosuppressive agents can interfere with the development of active immunity after rabies vaccination.', 'Reduced neutralizing antibody response during post-exposure prophylaxis may leave the patient unprotected against rabies.', 'Immunosuppressive agents are not given during post-exposure prophylaxis unless essential for another condition; in immunosuppressed patients, serum rabies antibody is tested (e.g., on Day 14) to confirm an adequate response.', 'RabAvert (rabies vaccine, PCECV) FDA label (DailyMed), Section 5 Altered Immunocompetence and Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=84b7a672-eeb1-4527-84ac-68196b156be2)', true),
    ('med_rabies_immunoglobulin', 'med_rabies_vaccine', 'caution', 'Rabies immunoglobulin provides passive neutralizing antibody but can partially suppress the active antibody response to rabies vaccine if given in excess or at the same site.', 'Standard complementary combination for category III exposures in previously unvaccinated persons; an excessive or repeated RIG dose may impair vaccine immunogenicity.', 'Give a single RIG dose (HRIG 20 IU/kg) infiltrated into and around the wound(s), with any remainder IM at a site distant from the vaccine; never in the same syringe or anatomical site as the vaccine; do not exceed the recommended dose; RIG is not given to previously vaccinated persons.', 'HYPERRAB (rabies immune globulin [human]) FDA label (DailyMed), Section 2 Dosage and Administration and Section 7 Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f82880b8-998c-4659-8f20-6dcc81f258e9)', true),
    ('med_ciprofloxacin', 'med_zinc_sulfate', 'caution', 'Zinc and other multivalent cations form chelation complexes with fluoroquinolones in the gut, reducing ciprofloxacin absorption.', 'Markedly reduced ciprofloxacin bioavailability can result in treatment failure, relevant when zinc is given with antibiotics in pediatric diarrhea.', 'Administer ciprofloxacin at least 2 hours before or 6 hours after zinc-containing products.', 'Ciprofloxacin tablets FDA label (DailyMed), Section 2 and Section 7 (products containing calcium, iron or zinc) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=5f4e80a1-0225-63dd-e053-2991aa0aa7fb)', true),
    ('med_cetirizine', 'med_nirmatrelvir_ritonavir', 'safe', 'Cetirizine is minimally metabolized by CYP3A. Full-dose ritonavir (600 mg twice daily) increased cetirizine AUC by 42%, similar to exposures seen in older adults or mild renal impairment.', 'With ritonavir used as a pharmacokinetic booster, a clinically significant interaction is not expected.', 'Can be coadministered without dose adjustment (nirmatrelvir itself was not studied; assessment is based on cetirizine''s minimal metabolism).', 'Liverpool HIV Drug Interactions: Ritonavir + Cetirizine (No Interaction Expected) (https://www.hiv-druginteractions.org/interactions/67417)', true);
INSERT INTO _seed_interaction_rules (id, name, severity, description, clinical_significance, recommendation, required_condition_id, source_attribution, is_published) VALUES
    ('triple_whammy', 'Triple whammy (RAAS blocker + diuretic + NSAID)', 'avoid', 'An ACE inhibitor or ARB (reduced efferent arteriolar tone), a diuretic (volume depletion) and an NSAID (afferent vasoconstriction from prostaglandin inhibition) together impair renal autoregulation.', 'Associated with acute kidney injury, particularly in elderly, volume-depleted or renally impaired patients; the losartan and enalapril labels warn that NSAIDs may cause renal deterioration including acute renal failure in patients on diuretic therapy.', 'Avoid adding an NSAID to a RAAS blocker plus diuretic; use paracetamol for analgesia. If unavoidable, use briefly with monitoring of renal function and potassium.', NULL, 'Losartan potassium tablets FDA label Section 7.3; Enalapril maleate FDA label, Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1dadbe02-289c-4312-9e65-40f3314dcc31)', true),
    ('raas_k_sparing_ckd', 'RAAS blocker + potassium-sparing diuretic in chronic kidney disease', 'caution', 'ACE inhibitors/ARBs and spironolactone both reduce renal potassium excretion; impaired renal function further limits potassium elimination.', 'Markedly increased risk of severe hyperkalemia; the spironolactone label states patients with renal impairment are at increased risk and ACE inhibitors/ARBs further increase it.', 'Combination is used in heart failure only with close monitoring: check potassium within 1 week of initiation or titration and regularly thereafter; at eGFR 30-50 mL/min/1.73 m2 consider starting spironolactone at 25 mg every other day. Generally avoided when serum potassium exceeds 5.0 mmol/L or eGFR is severely reduced.', 'renal_impairment', 'ALDACTONE (spironolactone) FDA label, Sections 2.2, 5.1, 7.1 and 8.6 (https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/012151s080lbl.pdf)', true),
    ('anticoagulant_antiplatelet_nsaid', 'Anticoagulant + antiplatelet + NSAID', 'avoid', 'Warfarin anticoagulation combined with platelet inhibition and NSAID-related platelet dysfunction and GI mucosal injury.', 'Very high risk of major and gastrointestinal bleeding; the warfarin and NSAID labels describe synergistic bleeding risk.', 'Avoid NSAIDs in patients on combined anticoagulant and antiplatelet therapy; use paracetamol for analgesia and consider gastroprotection.', NULL, 'Warfarin sodium FDA label Section 7; PLAVIX FDA label Sections 7.4-7.5; Ibuprofen FDA label Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=0cbce382-9c88-4f58-ae0f-532a841e8f95)', true),
    ('dual_antiplatelet_nsaid', 'Dual antiplatelet therapy + NSAID', 'avoid', 'Aspirin plus clopidogrel (two distinct antiplatelet agents) combined with an NSAID adds GI mucosal injury and further platelet inhibition; ibuprofen may also blunt aspirin''s antiplatelet effect.', 'Increased risk of gastrointestinal bleeding in patients on dual antiplatelet therapy (typically after acute coronary syndrome or stenting) and possible loss of aspirin cardioprotection.', 'Avoid NSAIDs during dual antiplatelet therapy; use paracetamol for analgesia and ensure gastroprotection where indicated.', NULL, 'PLAVIX FDA label Section 7.4; Advil Dual Action OTC Drug Facts (aspirin warning) (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=de8b0b67-eb25-4684-83b5-7ad785314227)', true),
    ('steroid_nsaid_ulcer', 'Systemic corticosteroid + NSAID with peptic ulcer disease', 'avoid', 'Systemic glucocorticoids and NSAIDs have additive injurious effects on the gastric mucosa.', 'High risk of ulcer complications and GI bleeding in patients with peptic ulcer or previous GI bleed; oral corticosteroid use is a recognised risk factor for NSAID-associated GI bleeding.', 'Avoid NSAIDs in patients with peptic ulcer who are taking systemic corticosteroids; use paracetamol and provide PPI gastroprotection if a steroid is required.', 'peptic_ulcer', 'Prednisone tablets FDA label, Precautions - Drug Interactions; Ibuprofen FDA label, GI bleeding warning (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=10fe5a3b-84dc-4600-87c2-b80c97ce18cf)', true),
    ('nsaid_raas_ckd', 'NSAID + RAAS blocker in chronic kidney disease', 'avoid', 'NSAID-induced afferent arteriolar vasoconstriction combined with ACE inhibitor/ARB efferent vasodilation reduces glomerular filtration in kidneys dependent on prostaglandins.', 'Deterioration of renal function, including possible acute renal failure, and hyperkalemia in patients with compromised renal function.', 'Avoid NSAIDs in patients with chronic kidney disease taking an ACE inhibitor or ARB; if unavoidable, use briefly with monitoring of renal function and potassium.', 'renal_impairment', 'Losartan potassium tablets FDA label Sections 5.3 and 7.3; Enalapril maleate FDA label, Precautions - Drug Interactions (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=1dadbe02-289c-4312-9e65-40f3314dcc31)', true),
    ('raas_k_sparing_nsaid', 'RAAS blocker + potassium-sparing diuretic + NSAID', 'avoid', 'Three potassium-retaining drugs (ACE inhibitor/ARB, spironolactone and NSAID) combined with NSAID-related reduction in renal perfusion.', 'Risk of severe hyperkalemia and acute kidney injury; the spironolactone label lists ACE inhibitors, ARBs and NSAIDs as drugs that increase potassium.', 'Avoid NSAIDs in patients taking a RAAS blocker with spironolactone; use paracetamol. If unavoidable, monitor potassium and renal function closely.', NULL, 'ALDACTONE (spironolactone) FDA label, Sections 5.1 and 7.1 (https://www.accessdata.fda.gov/drugsatfda_docs/label/2025/012151s080lbl.pdf)', true),
    ('triple_antithrombotic', 'Triple antithrombotic therapy (anticoagulant + two antiplatelets)', 'avoid', 'Warfarin combined with aspirin and clopidogrel produces independent, additive effects on coagulation and platelet function.', 'Highest bleeding-risk antithrombotic combination; reserved for limited periods in specific situations (e.g., atrial fibrillation after coronary stenting).', 'Avoid outside a specialist-defined indication; if used, keep duration as short as possible, use gastroprotection and monitor INR and bleeding closely.', NULL, 'PLAVIX FDA label Section 7.5; Warfarin sodium FDA label Section 7 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=de8b0b67-eb25-4684-83b5-7ad785314227)', true),
    ('hypokalemia_steroid_loop_beta_agonist', 'Systemic corticosteroid + loop diuretic + beta-2 agonist (hypokalemia)', 'caution', 'Corticosteroids and loop diuretics increase urinary potassium loss, while beta-2 agonists shift potassium into cells.', 'Additive hypokalemia with risk of ECG changes and arrhythmia, e.g., during treatment of an acute asthma or COPD exacerbation in a patient with heart failure.', 'Monitor serum potassium (and ECG where indicated); replace potassium as required.', NULL, 'Prednisone tablets FDA label (potassium-depleting agents); LASIX FDA label (hypokalemia with corticosteroids); Albuterol HFA FDA label Section 7.2 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=10fe5a3b-84dc-4600-87c2-b80c97ce18cf)', true),
    ('cotrimoxazole_raas_k_sparing_hyperkalemia', 'Hyperkalemia triad (co-trimoxazole + RAAS blocker + potassium-sparing diuretic)', 'avoid', 'Trimethoprim blocks distal-nephron sodium channels (amiloride-like), ACE inhibitors/ARBs lower aldosterone, and spironolactone antagonizes the mineralocorticoid receptor; all three reduce renal potassium excretion.', 'The co-trimoxazole label warns that even recommended doses may cause hyperkalemia when drugs known to induce hyperkalemia are given concomitantly; combining all three compounds the risk of severe hyperkalemia, especially in older adults and renal impairment.', 'Prefer an alternative antibiotic; if co-trimoxazole is unavoidable, check serum potassium and creatinine before and within a few days of starting, and consider temporarily holding spironolactone.', NULL, 'BACTRIM FDA label (DailyMed), Precautions - Hyperkalemia and Drug Interactions; EMA CMDh 2015 spironolactone/trimethoprim conclusions; Antoniou et al., Arch Intern Med 2010 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f59d0c04-9c66-4d53-a0e1-cb55570deb62)', true),
    ('cotrimoxazole_raas_ckd', 'Co-trimoxazole + RAAS blocker in chronic kidney disease', 'caution', 'Trimethoprim reduces distal potassium secretion; with an ACE inhibitor or ARB and reduced renal function, potassium elimination is further impaired and co-trimoxazole components accumulate.', 'The label states hyperkalemia may occur at recommended doses in patients with renal insufficiency or when drugs known to induce hyperkalemia are given concomitantly; half-lives of both components increase in severe renal impairment.', 'Adjust co-trimoxazole dose for creatinine clearance, monitor serum potassium closely, and consider an alternative antibiotic when clinically appropriate.', 'renal_impairment', 'BACTRIM FDA label (DailyMed), Precautions - Hyperkalemia; Dosage in renal impairment (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=f59d0c04-9c66-4d53-a0e1-cb55570deb62)', true),
    ('tenofovir_nsaid_ckd', 'Tenofovir DF + NSAID in chronic kidney disease', 'avoid', 'Tenofovir DF is renally eliminated and can cause tubular injury; NSAIDs reduce renal perfusion; pre-existing kidney disease reduces reserve.', 'Acute renal failure has been reported after initiation of high-dose or multiple NSAIDs in patients with renal risk factors who were stable on tenofovir DF.', 'Avoid NSAIDs with tenofovir DF in chronic kidney disease; use paracetamol for analgesia. Tenofovir DF dosing interval is adjusted for creatinine clearance below 50 mL/min, with monitoring of creatinine, urine glucose/protein and phosphorus.', 'renal_impairment', 'VIREAD (tenofovir disoproxil fumarate) FDA label (DailyMed), Sections 5.2 and 7.1 (https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=33fd6418-fbdc-42ca-a50d-ce2a476a5418)', true);
